void QAMDEM::mix( cdata_t din, cdata_t *dout_mix, cphase_t ph_offset ) {
#pragma HLS ALLOCATION instances=mul limit=1 operation
#35 "./qam_dem.h"

    cdata_t t_dout;

    t_dout.i = din.i * ph_offset.i;
    t_dout.i -= din.q * ph_offset.q;
    t_dout.q = din.i * ph_offset.q;
    t_dout.q += din.q * ph_offset.i;

    *dout_mix = t_dout;

}

void QAMDEM::slicer ( qam_t qam, cdata_t dout_mix, hd_t *hd_out, cdata_t *sd_out, error_t *err ) {

ap_fixed<5,1,SC_TRN,SC_SAT> clip_i, clip_q;

clip_i = dout_mix.i;
clip_q = dout_mix.q;

hd_t tmp_hd;
error_t tmp_err;

    tmp_hd.i[4] = clip_i[4];
    tmp_hd.i[3] = 1;
    tmp_hd.q[4] = clip_q[4];
    tmp_hd.q[3] = 1;

  *sd_out = dout_mix;
  *hd_out = tmp_hd;

  tmp_err.i = dout_mix.i - tmp_hd.i;
  tmp_err.q = dout_mix.q - tmp_hd.q;

  *err = tmp_err;

}

void QAMDEM::phase_recovery (
  hd_t hd_out,
  cdata_t sd_out,
  loop_int_t *loop_integ,
  loop_out_t *loop_out,
  cphase_t *ph_offset,
  ctl_crec_t control ) {


phase_t ph_est;
compute_phase (
    hd_out,
    sd_out,
    &ph_est);

loop_int_t t_loop_integ;
loop_out_t t_loop_out;
loop_filter(
    ph_est,
    &t_loop_integ,
    &t_loop_out,
    control);

ap_fixed<16,1> tphase;
cphase_t t_ph_offset;
vco (
    t_loop_out,
    &tphase,
    &t_ph_offset );

*loop_integ = t_loop_integ;
*loop_out = t_loop_out;
*ph_offset = t_ph_offset;

}

void QAMDEM::compute_phase (
    hd_t hd_out,
    cdata_t sd_out,
    phase_t *ph_est) {

    phase_t tmp;

    tmp = hd_out.i * sd_out.q;
    //cout << "tmp: " << tmp << ", ";
    tmp -= hd_out.q * sd_out.i;
    //cout << "tmp: " << tmp << ", " << endl;

    *ph_est = tmp;

}

void QAMDEM::loop_filter(
    phase_t din,
    loop_int_t *loop_integ,
    loop_out_t *loop_out,
    ctl_crec_t control) {


ap_fixed<28,2,SC_TRN,SC_WRAP> din_long;
ap_fixed<28,2,SC_TRN,SC_WRAP> p_out;
ap_fixed<28,2,SC_TRN,SC_WRAP> i_out;
ap_fixed<28,2,SC_TRN,SC_WRAP> i_sum;
ap_fixed<28,2,SC_TRN,SC_WRAP> tmp_sum;
ap_fixed<28,2,SC_TRN,SC_SAT> sum;

static ap_fixed<28,2,SC_TRN,SC_SAT> i_reg = 0;

din_long = din; // to allow shift right

p_out = din_long >> control.lf_p;
i_out = din_long >> (9 + control.lf_i);

i_sum = i_out + i_reg;
sum = i_sum + p_out;

if (control.reg_clr ==1)
  i_reg = control.reg_init;
else
  i_reg = i_sum;

tmp_sum = sum >> control.lf_out_gain;
*loop_integ = i_reg;
*loop_out = tmp_sum;

//cout << " din: " << din << "  pout: " << p_out  << "  i_out:" << i_out <<endl;

}

