                    #if defined(MUL32) || defined(MUL64) || defined(DIV) || defined(REM)
                case FUNCT7_MUL: // MUL, MULH, MULHSU, MULHU, DIV, DIVU, REM, REMU
                    switch (insn.range(14, 12)) {
