    inline friend void sc_trace(sc_trace_file * tf, const dcache_out_t & object, const std::string & in_name) {
        sc_trace(tf, object.data, in_name + std::string(".data"));
        sc_trace(tf, object.hit, in_name + std::string(".hit"));
    }

    //
    // stream operator.
