        for (i = 0; i < DCACHE_WAYS; i++) {
            cache_tag[0][i] = dcache_tags[index][i];
            cache_data[0][i] = dcache_data[index][i];

            if ((tag == cache_tag[0][i].tag) && (cache_tag[0][i].valid)) {

                tmp_data = cache_data[0][i];
                tmp_tag = cache_tag[0][i];
                dout.hit = true;
