/*	
	@author VLSI Lab, EE dept., Democritus University of Thrace

	@brief Header file for writeback stage.

	@note Changes from HL5

		- Use of HLSLibs connections for communication with the rest of the processor.

		- Memory is outside of the processor

*/

#ifndef __WRITEBACK__H
#define __WRITEBACK__H

#ifndef __SYNTHESIS__
    #include <sstream>
#endif

#ifndef NDEBUG
    #include <iostream>
    #define DPRINT(msg) std::cout << msg;
#endif


#include "drim4hls_datatypes.h"
#include "defines.h"
#include "globals.h"

#include <mc_connections.h>

SC_MODULE(writeback) {
    #ifndef __SYNTHESIS__
    struct writeback_out // TODO: fix all sizes
    {
        //
        // Member declarations.
        //		
        unsigned int aligned_address;
        sc_uint < XLEN > load_data;
        sc_uint < XLEN > store_data;
        std::string load;
        std::string store;

    }
    writeback_out_t;
    #endif

    // FlexChannel initiators
    Connections::In < exe_out_t > CCS_INIT_S1(din);
    Connections::In < dmem_out_t > CCS_INIT_S1(dmem_out);

    Connections::Out < mem_out_t > CCS_INIT_S1(dout);
    Connections::Out < dmem_in_t > CCS_INIT_S1(dmem_in);

    // Clock and reset signals
    sc_in < bool > CCS_INIT_S1(clk);
    sc_in < bool > CCS_INIT_S1(rst);

    // Member variables
    exe_out_t input;
    dmem_in_t dmem_dout;
    dmem_out_t dmem_din;
    mem_out_t output;

    sc_uint < DATA_SIZE > mem_dout;
    sc_uint < XLEN > dmem_data;

    // Constructor
    SC_CTOR(writeback): din("din"), dout("dout"), dmem_in("dmem_in"), dmem_out("dmem_out"), clk("clk"), rst("rst") {
        SC_THREAD(writeback_th);
        sensitive << clk.pos();
        async_reset_signal_is(rst, false);
    }

    void writeback_th(void) {
        WRITEBACK_RST: {
            din.Reset();
            dmem_out.Reset();

            dout.Reset();
            dmem_in.Reset();

            // Write dummy data to decode feedback.
            output.regfile_address = 0;
            output.regfile_data = 0;
            output.regwrite = 0;
            output.tag = 0;

            dmem_data = 0;
            mem_dout = 0;
        }

        #pragma hls_pipeline_init_interval 1
        #pragma pipeline_stall_mode flush
        WRITEBACK_BODY: while (true) {

            // Get
            input = din.Pop();

            #ifndef __SYNTHESIS__
                writeback_out_t.aligned_address = 0;
                writeback_out_t.load_data = 0;
                writeback_out_t.store_data = 0;
                writeback_out_t.load = "NO_LOAD";
                writeback_out_t.store = "NO_STORE";
            #endif

            // Compute
            // *** Memory access.
			dmem_data = 0;
            // WARNING: only supporting aligned memory accesses
            // Preprocess address

right_context:
            sc_uint< 5 > byte_index = (sc_uint< 5 >)((aligned_address & 0x3) << 3);
            sc_uint< 5 > halfword_index = (sc_uint< 5 >)((aligned_address & 0x2) << 3);

            aligned_address = aligned_address >> 2;
            sc_uint < BYTE > db = (sc_uint < BYTE >) 0;
            sc_uint < 2 * BYTE > dh = (sc_uint < 2 * BYTE >) 0;
            sc_uint < XLEN > dw = (sc_uint < XLEN >) 0;

            dmem_dout.data_addr = aligned_address;

            dmem_dout.read_en = false;
            dmem_dout.write_en = false;


            #ifndef __SYNTHESIS__
            if (sc_uint < 3 > (input.ld) != NO_LOAD || sc_uint < 2 > (input.st) != NO_STORE) {
                if (input.mem_datain.to_uint() == 0x11111111 ||
                    input.mem_datain.to_uint() == 0x22222222 ||
                    input.mem_datain.to_uint() == 0x11223344 ||
                    input.mem_datain.to_uint() == 0x88776655 ||
                    input.mem_datain.to_uint() == 0x12345678 ||
                    input.mem_datain.to_uint() == 0x87654321) {
                    std::stringstream stm;
                    stm << hex << "D$ access here2 -> 0x" << aligned_address << ". Value: " << input.mem_datain.to_uint() << std::endl;
                }
                //sc_assert(aligned_address < DCACHE_SIZE);
            }
            #endif

			if (input.ld != NO_LOAD) { // a load is requested

                dmem_dout.read_en = true;
                dmem_in.Push(dmem_dout);

                dmem_din = dmem_out.Pop();
                dmem_data = dmem_din.data_out;
                //freeze = false;
                switch (input.ld) { // LOAD
                case LB_LOAD:
                    db = dmem_data.range(byte_index + BYTE - 1, byte_index);
                    mem_dout = ext_sign_byte(db);

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "LB_LOAD";
                    #endif

                    break;
                case LH_LOAD:
                    dh = dmem_data.range(halfword_index + 2 * BYTE - 1, halfword_index);
                    mem_dout = ext_sign_halfword(dh);

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "LH_LOAD";
                    #endif

                    break;
                case LW_LOAD:
                    dw = dmem_data;
                    mem_dout = dw;

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "LW_LOAD";
                    #endif

                    break;
                case LBU_LOAD:
                    db = dmem_data.range(byte_index + BYTE - 1, byte_index);
                    mem_dout = ext_unsign_byte(db);

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "LBU_LOAD";
                    #endif

                    break;
                case LHU_LOAD:
                    //dh = dmem_data.range(halfword_index + 2 * BYTE - 1, halfword_index);
                    //dh = dmem_data.slc< 2 * BYTE >(halfword_index);
                    //dh.set_slc(0, dmem_data.slc< 2 * BYTE >(halfword_index));
                    dh = dmem_data.range(halfword_index + 2 * BYTE - 1, halfword_index);
                    mem_dout = ext_unsign_halfword(dh);

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "LHU_LOAD";
                    #endif

                    break;
                default:

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "NO_LOAD";
                    #endif

                    break; // NO_LOAD
                }
            } else if (input.st != NO_STORE) { // a store is requested

                dmem_dout.write_en = true;

                switch (input.st) { // STORE
                case SB_STORE: // store 8 bits of rs2

					db = input.mem_datain.range(BYTE - 1, 0).to_uint();
                    dmem_data.range(byte_index + BYTE - 1, byte_index) = db;

                    #ifndef __SYNTHESIS__
                    writeback_out_t.store_data = db;
                    writeback_out_t.store = "SB_STORE";
                    #endif

					break;
                case SH_STORE: // store 16 bits of rs2

					dh = input.mem_datain.range(2 * BYTE - 1, 0).to_uint();
                    dmem_data.range(byte_index + BYTE - 1, byte_index) = dh;

                    #ifndef __SYNTHESIS__
                    writeback_out_t.store_data = dh;
                    writeback_out_t.store = "SH_STORE";
                    #endif

                    break;
                case SW_STORE: // store rs2
                    dw = input.mem_datain.to_uint();
                    dmem_data = dw;

                    #ifndef __SYNTHESIS__
                    writeback_out_t.store_data = dw;
                    writeback_out_t.store = "SW_STORE";
                    #endif

                    break;
                default:

                    #ifndef __SYNTHESIS__
                    writeback_out_t.store = "NO_STORE";
                    #endif

                    break; // NO_STORE
                }

                dmem_dout.data_in = dmem_data;
                dmem_in.Push(dmem_dout);
            }
            // *** END of memory access.

            /* Writeback */
            output.regwrite = input.regwrite;
            output.regfile_address = input.dest_reg;
            output.regfile_data = (input.memtoreg[0] == 1) ? mem_dout : input.alu_res;
            output.tag = input.tag;
            output.pc = input.pc;

            // Put
		    dout.Push(output);
            #ifndef __SYNTHESIS__
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "load= " << writeback_out_t.load << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "store= " << writeback_out_t.store << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "input.regwrite=" << input.regwrite << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "regwrite=" << output.regwrite << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "aligned_address=" << aligned_address << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "mem_dout=" << mem_dout << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "input.alu_res=" << input.alu_res << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "output.regfile_address=" << output.regfile_address << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "output.regfile_data=" << output.regfile_data << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "input.memtoreg=" << input.memtoreg << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "writeback_out_t.store_data =" << writeback_out_t.store_data  << endl);
            DPRINT(endl);
            #endif
            wait();
        }
    }

    /* Support functions */

    // Sign extend byte read from memory. For LB
    sc_uint < XLEN > ext_sign_byte(sc_uint < BYTE > read_data) {
		if (read_data[7] == 1) {

			return (sc_uint < BYTE * 3 > (16777216), read_data);

		}
		else {

			return (sc_uint < BYTE * 3 > (0), read_data);
		}
    }

    // Zero extend byte read from memory. For LBU
    sc_uint < XLEN > ext_unsign_byte(sc_uint < BYTE > read_data) {

		return (sc_uint < BYTE * 3 > (0), read_data);       
    }

    // Sign extend half-word read from memory. For LH
    sc_uint < XLEN > ext_sign_halfword(sc_uint < BYTE * 2 > read_data) {

        if (read_data[15] == 1) {

            return (sc_uint < BYTE * 2 > (65535), read_data);
        }
        else {

            return (sc_uint < BYTE * 2 > (0), read_data);
        }
    }

    // Zero extend half-word read from memory. For LHU
    sc_uint < XLEN > ext_unsign_halfword(sc_uint < BYTE * 2 > read_data) {

		return (sc_uint < BYTE * 2 > (0), read_data);
    }

};

#endif

left_context:
/*	
	@author VLSI Lab, EE dept., Democritus University of Thrace

	@brief Header file for decode stage

	@note Changes from HL5
		- Implements the logic only for the decode part from fedec.hpp.

		- Use of HLSLibs connections for communication with the rest of the processor.

		- Stall mechanism manages data dependencies, dynamic load/write memory stalls
		  and change of program direction.


*/

#ifndef __DEC__H
#define __DEC__H

#ifndef NDEBUG
    #include <iostream>
    #define DPRINT(msg) std::cout << msg;
#endif

#include "drim4hls_datatypes.h"
#include "defines.h"
#include "globals.h"

#include <mc_connections.h>
#include <ac_int.h>

SC_MODULE(decode) {
    public:
    // Clock and reset signals
    sc_in < bool > CCS_INIT_S1(clk);
    sc_in < bool > CCS_INIT_S1(rst);
    // FlexChannel initiators
    Connections::Out < de_out_t > CCS_INIT_S1(dout);
    Connections::Out < de_out_t > CCS_INIT_S1(dout_fp);
    Connections::Out < fe_in_t > CCS_INIT_S1(fetch_dout);
    Connections::In < mem_out_t > CCS_INIT_S1(feed_from_wb);
    Connections::In < fe_out_t > CCS_INIT_S1(fetch_din);
    Connections::In < reg_forward_t > CCS_INIT_S1(fwd_exe);
    Connections::In < reg_forward_t > CCS_INIT_S1(fwd_exefp);

    // End of simulation signal.
    sc_out < bool > CCS_INIT_S1(program_end);

    // Instruction counters
    sc_out < long int > CCS_INIT_S1(icount);
    sc_out < long int > CCS_INIT_S1(j_icount);
    sc_out < long int > CCS_INIT_S1(b_icount);
    sc_out < long int > CCS_INIT_S1(m_icount);
    sc_out < long int > CCS_INIT_S1(o_icount);

    bool jump;
    bool branch;
    // Trap signals. TODO: not used. Left for future implementations.
    sc_signal < bool > CCS_INIT_S1(trap); //sc_out
    sc_signal < ac_int < LOG2_NUM_CAUSES, false > > CCS_INIT_S1(trap_cause); //sc_out

    bool freeze;
    // Flushes current instruction in order to sychronize processor with a
    // change of direction in the execution
    bool flush;

    bool forward_success_rs1;
    bool forward_success_rs2;

    bool forward_success_frs1;
    bool forward_success_frs2;
    bool forward_success_frs3;

    bool load_instruction;
    ac_int < PC_LEN, true > load_pc;

    bool fp_insn_rs1;
    bool fp_insn_rs2;
    bool fp_insn_rs3;
    bool fp_curr_insn;

    ac_int < INSN_LEN, false > insn; // Contains full instruction fetched from IMEM. Used in decoding.
    ac_int < PC_LEN, true > pc; // Contains PC for the current instruction that is decoded   
    // NB. x0 is included in this regfile so it is not a real hardcoded 0
    // constant. The writeback section of fedec has a guard fro writes on
    // x0. For double protection, some instructions that want to write into
    // x0 will have their regwrite signal forced to false.
    ac_int < XLEN, false > regfile[REG_NUM];
    ac_int < FLEN, false > fregfile[FREG_NUM];
    // Keeps track of in-flight instructions that are going to overwrite a
    // register. Implements a primitive stall mechanism for RAW hazards.
    ac_int < XLEN + 1, false > sentinel[REG_NUM];
    ac_int < XLEN + 1, false > fsentinel[REG_NUM];

    ac_int < TAG_WIDTH, false > tag;
    // Stalls processor and sends a nop operation to the execute stage
    sc_uint < OPCODE_SIZE > opcode;

    int position;
    // Member variables (DECODE)
    de_in_t self_feed; // Contains branch and jump data		 
    mem_out_t feedinput; // Contains data from writeback stage
    mem_out_t feedinput_tmp; // Contains data from writeback stage
    de_out_t output; // Contains data for the execute stage
    fe_out_t input; // Contains data from the fetch stage
    fe_in_t fetch_out; // Contains data for the fetch stage about processor stalls

    reg_forward_t fwd;
    reg_forward_t temp_fwd;

    fe_out_t fetch_in; // Buffer for the data coming from the fetch stage

    unsigned int imem_data; // Contains instruction data

	ac_int< 32, false > addr_tmp;
	ac_int< 5, false > zero_reg_addr;

    bool flush_next;
    bool new_instr;
    int position_fwd;
    int position_fwdfp;
    int position_wb;

    ac_int < DCACHE_INDEX_WIDTH, false > last_ldst_addr;
    ac_int < DCACHE_INDEX_WIDTH, false > last_ldst_addr_temp;
    bool last_ldst_valid;

    SC_CTOR(decode): clk("clk"),
    rst("rst"),
    dout("dout"),
    feed_from_wb("feed_from_wb"),
    fetch_din("fetch_din"),
    fetch_dout("fetch_dout"),
    program_end("program_end"),
    fwd_exe("fwd_exe"),
    icount("icount"),
    j_icount("j_icount"),
    b_icount("b_icount"),
    m_icount("m_icount"),
    o_icount("o_icount") {

        SC_THREAD(decode_th);
        sensitive << clk.pos();
        async_reset_signal_is(rst, false);

    }

    #ifndef __SYNTHESIS__
    //for debugging purposes
    struct debug_dout { //
        // Member declarations.
        //
        std::string regwrite;
        std::string memtoreg;
        std::string ld;
        std::string st;
        std::string alu_op;
        std::string alu_src;
        bool rs1_forward;
        bool rs2_forward;
        bool branch_taken;
        ac_int < XLEN, false > rs1;
        ac_int < XLEN, false > rs2;
        std::string dest_reg;
        int pc;
        int aligned_pc;
        ac_int < XLEN - 12, false > imm_u;
        ac_int < TAG_WIDTH, false > tag;

    }
    debug_dout_t;
    #endif

    void decode_th(void) {
        DECODE_RST: {
            dout.Reset();
            dout_fp.Reset();
            fetch_din.Reset();
            feed_from_wb.Reset();
            fetch_dout.Reset();
            fwd_exe.Reset();
            fwd_exefp.Reset();

            // Init. sentinel flags to zero.
            for (int i = 0; i < REG_NUM; i++) {
                sentinel[i] = SENTINEL_INIT;
            }

            // Program has not completed
            program_end.write(false);
            icount.write(0); // any
            j_icount.write(0); // jump
            b_icount.write(0); // branch
            m_icount.write(0); // load, store
            o_icount.write(0); // other

            addr_tmp = 0;
            zero_reg_addr = 0;

            freeze = false;
            flush = false;
	        flush_next = false;

            fp_insn_rs1 = false;
			fp_insn_rs2 = false;
			fp_insn_rs3 = false;
			fp_curr_insn = false;

            forward_success_rs1 = false;
            forward_success_rs2 = false;
            forward_success_frs1 = false;
            forward_success_frs2 = false;
            forward_success_frs3 = false;

            position = 0;
            insn = 0;
            branch = false;
            jump = false;
            pc = -4;
            load_instruction = false;
            load_pc = -4;
            new_instr = false;
            position_fwd = 0;
            position_wb = 0;
            fetch_out.address = 0;
            position_fwdfp = 0;

			last_ldst_valid = false;
			last_ldst_addr = 0;
			last_ldst_addr_temp = 0;

            wait();
        }

        #pragma hls_pipeline_init_interval 1
        #pragma pipeline_stall_mode flush
        DECODE_BODY: while (true) {
            // Retrieve data from instruction memory and fetch stage.
            // If processor stalls then just clear the channels from new data.

			if (!freeze) {
				fetch_in = fetch_din.Pop();
				pc = fetch_in.pc;
				imem_data = fetch_in.instr_data;
			}


            if (position_fwd == 1) {
				fwd = fwd_exe.Pop();
			}else {
				position_fwd = 1;
			}

			if (position_fwdfp == 1) {
				fwd = fwd_exefp.Pop();
			}else {
				position_fwdfp = 1;
			}

			if (position_wb == 2) {
				feedinput = feed_from_wb.Pop();

				if (feedinput.pc == load_pc && load_instruction) {
                    load_instruction = false;
                }
			}else {
				position_wb++;
			}

            if (feedinput.regwrite == 1 && feedinput.regfile_address != 0) { // Actual writeback.

				if (!feedinput.dest_freg) {
					regfile[feedinput.regfile_address] = feedinput.regfile_data; // Overwrite register.
				}else {
					fregfile[feedinput.regfile_address] = feedinput.regfile_data;
				}   

				if ((feedinput.pc == sentinel[feedinput.regfile_address].slc<32>(1)) && (sentinel[feedinput.regfile_address][0] == 1) && !feedinput.dest_freg) {
					sentinel[feedinput.regfile_address][0] = 0;
				}else if ((feedinput.pc == fsentinel[feedinput.regfile_address].slc<32>(1)) && (fsentinel[feedinput.regfile_address][0] == 1) && feedinput.dest_freg) {
					fsentinel[feedinput.regfile_address][0] = 0;
				}

            }

            flush_next = false;
            new_instr = false;

            insn = imem_data;

			forward_success_rs1 = false;
            forward_success_rs2 = false;

			forward_success_frs1 = false;
			forward_success_frs2 = false;
			forward_success_frs3 = false;

			output.dest_freg = false;

            new_instr = true;
            fp_curr_insn = false;

            #ifndef __SYNTHESIS__
            debug_dout_t.pc = pc;
            #endif

            output.pc = pc;
            fetch_out.pc = pc;
            // Increment some instruction counters
            //opcode = sc_uint < OPCODE_SIZE > (sc_bv < OPCODE_SIZE > (insn.range(6, 2)));
			opcode = insn.slc<OPCODE_SIZE>(2);

            if (opcode == OPC_LW || opcode == OPC_SW) {
                // Increment memory instruction counter
				m_icount.write(m_icount.read() + 1);
			}
            else if (opcode == OPC_JAL || opcode == OPC_JALR) {
				// Increment jump instruction counter
                j_icount.write(j_icount.read() + 1);
			} else if (opcode == OPC_BEQ) {
				// Increment branch instruction counter
				b_icount.write(b_icount.read() + 1);
            } else {
				// Increment other instruction counter
                o_icount.write(o_icount.read() + 1);
			}
            icount.write(icount.read() + 1);

           if (insn == 0x0000006f) {
                // jump to yourself (end of program).
                program_end.write(true);
            }

            fp_insn_rs1 = false;
			fp_insn_rs2 = false;
			fp_insn_rs3 = false;
			fp_curr_insn = false;

            ac_int < REG_ADDR, false > rs1_addr = insn.slc<REG_ADDR>(15);
            ac_int < REG_ADDR, false > rs2_addr = insn.slc<REG_ADDR>(20);
            ac_int < REG_ADDR, false > rs3_addr = insn.slc<REG_ADDR>(27);

			ac_int< 32, false > rs1_sent_pc = sentinel[rs1_addr].slc<32>(1);
			ac_int < 1, false > rs1_sent_valid = sentinel[rs1_addr][0];

            if (!fwd.ldst && fwd.pc == rs1_sent_pc && rs1_sent_valid == 1 && !fwd.freg) {
                forward_success_rs1 = true;
                output.rs1 = fwd.regfile_data;
                #ifndef __SYNTHESIS__
                debug_dout_t.rs1 = fwd.regfile_data;
                debug_dout_t.rs1_forward = forward_success_rs1;
                #endif
            } else if (!forward_success_rs1) {

                output.rs1 = regfile[rs1_addr];
                #ifndef __SYNTHESIS__
                debug_dout_t.rs1 = regfile[rs1_addr];
                debug_dout_t.rs1_forward = forward_success_rs1;
                #endif

            }

            ac_int < 32, false > rs2_sent_pc = sentinel[rs2_addr].slc<32>(1);
			ac_int < 1, false > rs2_sent_valid = sentinel[rs2_addr][0];

            if (!fwd.ldst && fwd.pc == rs2_sent_pc && rs2_sent_valid == 1 && !fwd.freg) {
                forward_success_rs2 = true;
                output.rs2 = fwd.regfile_data;
				#ifndef __SYNTHESIS__
                debug_dout_t.rs2 = fwd.regfile_data;
                debug_dout_t.rs2_forward = forward_success_rs2;
                #endif

            } else if (!forward_success_rs2) {

                output.rs2 = regfile[rs2_addr];
                #ifndef __SYNTHESIS__
                debug_dout_t.rs2 = regfile[rs2_addr];
                debug_dout_t.rs2_forward = forward_success_rs2;
                #endif


            }

            // *** Feedback to fetch data computation and put() section.
            // -- Address sign extensions.
            ac_int < 21, false> immjal_tmp;
            ac_int < 13, false> immbranch_tmp;

            immjal_tmp[0] = 0;
            immjal_tmp.set_slc(1, insn.slc<10>(21));
            immjal_tmp[11] = insn[20];
            immjal_tmp.set_slc(12, insn.slc<8>(12));
			immjal_tmp[20] = insn[31];

			immbranch_tmp[0] = 0;
            immbranch_tmp.set_slc(1, insn.slc<4>(8));
            immbranch_tmp.set_slc(5, insn.slc<6>(25));            
            immbranch_tmp[11] = insn[7];
			immbranch_tmp[12] = insn[31];

            self_feed.branch_address = sign_extend_branch(immbranch_tmp + pc);
            // -- Jump.
            fetch_out.branch_taken = false;
            fetch_out.btb_update = false;
            fetch_out.ras_update = false;
            fetch_out.address = pc + 4;
            jump = false;
            if (insn.slc<5>(2) == OPC_JAL) {
                self_feed.jump_address = sign_extend_jump(immjal_tmp + pc);
                jump = true;
                fetch_out.ras_update = true;
                fetch_out.bta = self_feed.jump_address;
                fetch_out.address = self_feed.jump_address;
            } else if (insn.slc<5>(2) == OPC_JALR) {
                ac_int < PC_LEN, false > extended;

right_context:
                self_feed.jump_address[0] = 0;

                jump = true;

                fetch_out.bta = self_feed.jump_address;
                fetch_out.address = self_feed.jump_address;
            }

            // -- Branch circuitry.
            branch = false;
            if (insn.slc<5>(2) == OPC_BEQ) { // BEQ,BNE, BLT, BGE, BLTU, BGEU
				fetch_out.btb_update = true;
				fetch_out.bta = self_feed.branch_address;
                switch (insn.slc<3>(12)) {
                case FUNCT3_BEQ:
                    if (output.rs1 == output.rs2) {
						branch = true; // BEQ taken.
						fetch_out.branch_taken = true;
						fetch_out.address = self_feed.branch_address;
						#ifndef __SYNTHESIS__
						debug_dout_t.branch_taken = true;
						#endif
					}

                    break;
                case FUNCT3_BNE:
                    if (output.rs1 != output.rs2) {
						branch = true; //BNE taken.
						fetch_out.branch_taken = true;
                        fetch_out.address = self_feed.branch_address;
                        #ifndef __SYNTHESIS__
                        debug_dout_t.branch_taken = true;
                        #endif
                    }
                    break;
                case FUNCT3_BLT:
                    if (output.rs1 < output.rs2) {
						branch = true; // BLT taken
						fetch_out.branch_taken = true;
						fetch_out.address = self_feed.branch_address;
                        #ifndef __SYNTHESIS__
                        debug_dout_t.branch_taken = true;
                        #endif
                    }
                    break;
                case FUNCT3_BGE:
                    if (output.rs1 >= output.rs2) {
						branch = true; // BGE taken.
						fetch_out.branch_taken = true;
						fetch_out.address = self_feed.branch_address;
                        #ifndef __SYNTHESIS__
                        debug_dout_t.branch_taken = true;
                        #endif
