                    trap = 0;
                    trap_cause = NULL_CAUSE;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.alu_op = "ALUOP_CSRRCI";
                    #endif
                    break;
                default:
                    output.alu_op = ALUOP_NULL;
                    trap = 0;
                    trap_cause = NULL_CAUSE;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.alu_op = "ALUOP_NULL";
                    #endif
                    SC_REPORT_ERROR(sc_object::name(), "Unimplemented SYSTEM instruction");
                    break;
                }
                break;
                #endif // --- End of System instructions decoding
			case OPC_FLW:

				output.alu_op = ALUOP_FADD;
                output.alu_src = ALUSRC_IMM_I;
                output.regwrite = 1;
                output.ld = LW_LOAD;
                output.st = NO_STORE;
                output.memtoreg = 1;
				trap = 0;
                trap_cause = NULL_CAUSE;
				output.flw = true;
				output.fsw = false;
				fp_curr_insn = false;
				output.dest_freg = true;

                break;
            case OPC_FSW:
				output.alu_op = ALUOP_FADD;
                output.alu_src = ALUSRC_IMM_S;
                output.regwrite = 0;
                output.ld = NO_LOAD;
                output.st = SW_STORE;
                output.memtoreg = 0;
                trap = 0;
                trap_cause = NULL_CAUSE;
				output.flw = false;
				output.fsw = true;
				output.imm_u.set_slc(0, insn.slc<5>(7));
				output.imm_u.set_slc(5, insn.slc<7>(25));
				fp_insn_rs2 = true;
				fp_curr_insn = false;

                break;
            case OPC_FMADDS:
				output.alu_op = ALUOP_FMADD;
                output.alu_src = ALUSRC_RS2;
                output.regwrite = 1;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.memtoreg = 0;
                trap = 0;
                trap_cause = NULL_CAUSE;
				output.flw = false;
				output.fsw = false;
				fp_insn_rs1 = true;
				fp_insn_rs2 = true;
				fp_insn_rs3 = true;
				fp_curr_insn = true;
				output.dest_freg = true;

                break;
            case OPC_FNMADDS:
				output.alu_op = ALUOP_FNMADD;
                output.alu_src = ALUSRC_RS2;
                output.regwrite = 1;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.memtoreg = 0;
                trap = 0;
                trap_cause = NULL_CAUSE;
				output.flw = false;
				output.fsw = false;
				fp_insn_rs1 = true;
				fp_insn_rs2 = true;
				fp_insn_rs3 = true;
				fp_curr_insn = true;
				output.dest_freg = true;

                break;
            case OPC_FMSUBS:
				output.alu_op = ALUOP_FMSUBS;
                output.alu_src = ALUSRC_RS2;
                output.regwrite = 1;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.memtoreg = 0;
                trap = 0;
                trap_cause = NULL_CAUSE;
				output.flw = false;
				output.fsw = false;
				fp_insn_rs1 = true;
				fp_insn_rs2 = true;
				fp_insn_rs3 = true;
				fp_curr_insn = true;
				output.dest_freg = true;

                break;
            case OPC_FNMSUBS:
				output.alu_op = ALUOP_FNMSUBS;
                output.alu_src = ALUSRC_RS2;
                output.regwrite = 1;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.memtoreg = 0;
                trap = 0;
                trap_cause = NULL_CAUSE;
				output.flw = false;
				output.fsw = false;
				fp_insn_rs1 = true;
				fp_insn_rs2 = true;
				fp_insn_rs3 = true;
				fp_curr_insn = true;
				output.dest_freg = true;

                break;
            case OPC_FADDS:
                output.alu_src = ALUSRC_RS2;
                output.regwrite = 1;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.memtoreg = 0;
                trap = 0;
                trap_cause = NULL_CAUSE;
				output.flw = false;
				output.fsw = false;
				fp_insn_rs1 = true;
				fp_insn_rs2 = true;
				fp_curr_insn = true;

				switch (insn.slc<FUNCT5_SIZE>(27)) {
					case FUNCT5_FADDS: // EBREAK, ECALL
						output.alu_op = ALUOP_FADD;
						output.dest_freg = true;
						break;
					case FUNCT5_FSUBS:
						output.alu_op = ALUOP_FSUB;
						output.dest_freg = true;
						break;
					case FUNCT5_FMULS:
						output.alu_op = ALUOP_FMUL;
						output.dest_freg = true;
						break;
					case FUNCT5_FDIVS:
						output.alu_op = ALUOP_FDIV;
						output.dest_freg = true;
						break;
					case FUNCT5_FMINS:
						output.dest_freg = true;
						switch (insn.slc<RM_SIZE>(12)) {

							case FRM_MIN: // FMIN.S
								output.alu_op = ALUOP_FMIN;
								break;
							case FRM_MAX: // FMAX.S
								output.alu_op = ALUOP_FMAX;
								break;
							default:
								output.alu_op = ALUOP_NULL;
								break;
						}
						break;
					case FUNCT5_FSQRTS:
						output.alu_op = ALUOP_FSQRT;
						fp_insn_rs2 = false;
						output.dest_freg = true;
						break;
					case FUNCT5_FCVTWS:
						output.dest_freg = false;
						switch (insn.slc<RS2_SIZE>(20)) {

							case RS2_W: // FCVT.W.S
								output.alu_op = ALUOP_FCVTWS;
								fp_insn_rs2 = false;
								break;
							case RS2_WU: // FCVT.WU.S
								output.alu_op = ALUOP_FCVTWUS;
								fp_insn_rs2 = false;
								break;
							default:
								output.alu_op = ALUOP_NULL;
								break;
						}

						break;
					case FUNCT5_FCVTSW:
						output.dest_freg = true;
						switch (insn.slc<RS2_SIZE>(20)) {

							case RS2_W: // FCVT.S.W
								output.alu_op = ALUOP_FCVTSW;
								fp_insn_rs1 = false;
								fp_insn_rs2 = false;
								break;
							case RS2_WU: // FCVT.S.WU
								output.alu_op = ALUOP_FCVTSWU;
								fp_insn_rs1 = false;
								fp_insn_rs2 = false;
								break;
							default:
								output.alu_op = ALUOP_NULL;
								break;
						}

						break;
					case FUNCT5_FSGNJS:
						output.dest_freg = true;
						switch (insn.slc<RM_SIZE>(12)) {

							case FRM_J: // FSGNJ.S
								output.alu_op = ALUOP_FSGNJ;
								break;
							case FRM_JN: // FSGNJN.S
								output.alu_op = ALUOP_FSGNJN;
								break;
							case FRM_JX: // FSGNJN.JX
								output.alu_op = ALUOP_FSGNJX;
								break;
							default:
								output.alu_op = ALUOP_NULL;
								break;
						}

						break;
					case FUNCT5_FMVXW:
						switch (insn.slc<RM_SIZE>(12)) {

							case FRM_FMVXW: // FCLASS
								output.alu_op = ALUOP_FMVXW;
								fp_insn_rs2 = false;
								break;
							case FRM_CLASS: // FCLASS
								output.alu_op = ALUOP_FCLASS;
								fp_insn_rs2 = false;
								//output.dest_freg = true;
								break;
							default:
								output.alu_op = ALUOP_NULL;
								break;
						}

						break;
					case FUNCT5_FMVWX:
						output.alu_op = ALUOP_FMVWX;
						fp_insn_rs1 = false;
						fp_insn_rs2 = false;
						output.dest_freg = true;
						break;
					case FUNCT5_FEQS:
						switch (insn.slc<RM_SIZE>(12)) {

							case FRM_FEQ: // FEQ.S
								output.alu_op = ALUOP_FEQ;
								break;
							case FRM_FLT: // FLT.S
								output.alu_op = ALUOP_FLT;
								break;
							case FRM_FLE: // FLE.S
								output.alu_op = ALUOP_FLE;
								break;
							default:
								output.alu_op = ALUOP_NULL;
								break;
						}

						break;
					default:
						output.alu_op = ALUOP_NULL;
						trap = 0;
						trap_cause = NULL_CAUSE;

						#ifndef __SYNTHESIS__
						debug_dout_t.alu_op = "ALUOP_NULL";
						#endif
						SC_REPORT_ERROR(sc_object::name(), "Unimplemented SYSTEM instruction");
						break;
                }
                break;
            default: // illegal instruction
                output.alu_src = ALUSRC_RS2;
                output.regwrite = 0;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.memtoreg = 0;
                trap = 1;
                trap_cause = ILL_INSN_CAUSE;
                output.alu_op = ALUOP_CSRRWI;
                output.imm_u.set_slc(8, (ac_int<CSR_ADDR, false>)MCAUSE_A); // force the CSR address to MCAUSE's
                output.flw = false;
				output.fsw = false;
				fp_insn_rs1 = false;
				fp_insn_rs2 = false;
				fp_insn_rs3 = false;

                #ifndef __SYNTHESIS__
                debug_dout_t.alu_src = "ALUSRC_RS2";
                debug_dout_t.regwrite = "REGWRITE NO";
                debug_dout_t.ld = "NO_LOAD";
                debug_dout_t.st = "NO_STORE";
                debug_dout_t.memtoreg = "MEMTOREG NO";
                debug_dout_t.alu_op = "ALUOP_CSRRWI";
                debug_dout_t.imm_u.set_slc(8, (ac_int<12, false>)MCAUSE_A);
                debug_dout_t.imm_u.set_slc(3, (ac_int<5>)ILL_INSN_CAUSE);
                #endif

                SC_REPORT_ERROR(sc_object::name(), "Unimplemented instruction");
                break;
            } // --- END of OPCODE switch
            // *** END of control word generation.

            ac_int< 32, false > frs1_sent_pc = fsentinel[rs1_addr].slc<32>(1);
			ac_int < 1, false > frs1_sent_valid = fsentinel[rs1_addr][0];

            if (!fwd.ldst && fwd.pc == frs1_sent_pc && frs1_sent_valid == 1 && fwd.freg && fp_insn_rs1) {
                forward_success_frs1 = true;
                output.rs1 = fwd.regfile_data;
                #ifndef __SYNTHESIS__
                debug_dout_t.rs1 = fwd.regfile_data;
                debug_dout_t.rs1_forward = forward_success_rs1;
                #endif
            } else if (fp_insn_rs1) {
				forward_success_frs1 = false;
                output.rs1 = fregfile[rs1_addr];
                #ifndef __SYNTHESIS__
                debug_dout_t.rs1 = fregfile[rs1_addr];
                debug_dout_t.rs1_forward = forward_success_rs1;
                #endif

            }

            ac_int < 32, false > frs2_sent_pc = fsentinel[rs2_addr].slc<32>(1);
			ac_int < 1, false > frs2_sent_valid = fsentinel[rs2_addr][0];

            if (!fwd.ldst && fwd.pc == frs2_sent_pc && frs2_sent_valid == 1 && fwd.freg && fp_insn_rs2) {
                forward_success_frs2 = true;
                output.rs2 = fwd.regfile_data;
				#ifndef __SYNTHESIS__
                debug_dout_t.rs2 = fwd.regfile_data;
                debug_dout_t.rs2_forward = forward_success_rs2;
                #endif

            } else if (fp_insn_rs2) {
                forward_success_frs2 = false;
                output.rs2 = fregfile[rs2_addr];
                #ifndef __SYNTHESIS__
                debug_dout_t.rs2 = fregfile[rs2_addr];
                debug_dout_t.rs2_forward = forward_success_rs2;
                #endif
            }

            ac_int < 32, false > frs3_sent_pc;
			ac_int < 1, false > frs3_sent_valid;

			if (fp_insn_rs3) {
				frs3_sent_pc = fsentinel[rs3_addr].slc<32>(1);
				frs3_sent_valid = fsentinel[rs3_addr][0];
			}else {
				frs3_sent_pc = 0;
				frs3_sent_valid = 0;
			}

            if (!fwd.ldst && fwd.pc == frs3_sent_pc && frs3_sent_valid == 1 && fwd.freg && fp_insn_rs3) {
                output.rs3 = fwd.regfile_data;
				forward_success_frs3 = true;
				#ifndef __SYNTHESIS__
                debug_dout_t.rs2 = fwd.regfile_data;
                debug_dout_t.rs2_forward = forward_success_frs3;
                #endif

            } else if (fp_insn_rs3) {
                output.rs3 = fregfile[rs3_addr];
                #ifndef __SYNTHESIS__
                debug_dout_t.rs2 = fregfile[rs3_addr];
                debug_dout_t.rs2_forward = forward_success_frs3;
                #endif
            }

            ac_int <XLEN, false> curr_temp_rs2 = 0;
            if (output.alu_src == ALUSRC_RS2) {
                curr_temp_rs2 = output.rs2;

            } else if (output.alu_src == ALUSRC_IMM_I) {
                curr_temp_rs2.set_slc(0, output.imm_u.slc<12>(8));
                if (output.imm_u[19] == 1) {
					curr_temp_rs2.set_slc(12, (ac_int < 20, false >) 1048575);
				}
            } else if (output.alu_src == ALUSRC_IMM_S) {
				curr_temp_rs2.set_slc(0, output.dest_reg);
                curr_temp_rs2.set_slc(5, output.imm_u.slc<7>(13));
                 if (curr_temp_rs2[11] == 1) {
					curr_temp_rs2.set_slc(12, (ac_int < 20, false >) 1048575);
				}

            } else {
				curr_temp_rs2.set_slc(0, (ac_int < 12, false >)0); 
				curr_temp_rs2.set_slc(12, output.imm_u.slc<20>(0));
            }

            last_ldst_addr_temp = (output.rs1 + curr_temp_rs2).slc<DCACHE_INDEX_WIDTH>(2 + DCACHE_OFFSET_WIDTH);

            if ((output.ld != NO_LOAD || output.st != NO_STORE || output.flw || output.fsw) 
				&& (last_ldst_addr_temp == last_ldst_addr) && last_ldst_valid && !freeze) {

                load_instruction = true;
                load_pc = pc;
            }

            freeze = false;
            if (load_instruction || (rs1_sent_valid && !forward_success_rs1 && !fp_insn_rs1) || (rs2_sent_valid && !forward_success_rs2 && !fp_insn_rs2)) {
				freeze = true;
			} 

			if (load_instruction || (frs1_sent_valid && !forward_success_frs1 && fp_insn_rs1) || (frs2_sent_valid && !forward_success_frs2 && fp_insn_rs2) || (frs3_sent_valid && !forward_success_frs3 && fp_insn_rs3)) {
				freeze = true;
			}  

            ac_int < 1, false > out_regwrite = output.regwrite;
            ac_int < 33, false > sen_input;

            if (!freeze && output.regwrite[0] == 1 && output.dest_reg != 0 ) {

                if (!output.dest_freg) {
					sentinel[output.dest_reg].set_slc(1,pc); // Set corresponding sentinel flag.
					sentinel[output.dest_reg][0] = 1;
				} else {
					fsentinel[output.dest_reg].set_slc(1,pc); // Set corresponding sentinel flag.
					fsentinel[output.dest_reg][0] = 1;
				}

                if (output.dest_reg == rs1_addr && !fp_insn_rs1) {
                    forward_success_rs1 = true;
                } else if (output.dest_reg == rs2_addr && !fp_insn_rs2) {
                    forward_success_rs2 = true;
                }

                if (output.dest_reg == rs1_addr && fp_insn_rs1) {
                    forward_success_frs1 = true;
                } else if (output.dest_reg == rs2_addr && fp_insn_rs2) {
                    forward_success_frs2 = true;
                }else if (output.dest_reg == rs3_addr && fp_insn_rs3) {
                    forward_success_frs3 = true;
                }
            }

            // *** Transform instruction into nop when freeze is active
            if (insn == 0 || freeze) {
                // Bubble.
                output.regwrite = 0;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.flw = false;
                output.fsw = false;
                output.alu_op = ALUOP_NULL;
                fetch_out.ras_update = false;
				fetch_out.btb_update = false;
                #ifndef __SYNTHESIS__
                debug_dout_t.regwrite = "REGWRITE NO";
                debug_dout_t.ld = "NO_LOAD";
                debug_dout_t.st = "NO_STORE";
                #endif
            }

            if (output.ld != NO_LOAD || output.st != NO_STORE || output.flw || output.fsw ) {
				last_ldst_addr = last_ldst_addr_temp;
				last_ldst_valid = true;
			}else {
				last_ldst_valid = false;
			}

            if (!freeze) {
				fetch_dout.Push(fetch_out);
			}

			if (fp_curr_insn) {
				dout_fp.Push(output);
				position_fwd = 0;
			} else {
				dout.Push(output);
				position_fwdfp = 0;
			}
			//dout.Push(output); // ----------------------------> comment later
            #ifndef __SYNTHESIS__
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "load_instruction=" << load_instruction << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "insn=" << insn << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "freeze= " << freeze << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "flush= " << flush << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "pc= " << debug_dout_t.pc << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "regwrite= " << debug_dout_t.regwrite << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "memtoreg= " << debug_dout_t.memtoreg << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "ld= " << debug_dout_t.ld << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "st= " << debug_dout_t.st << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "alu_op= " << debug_dout_t.alu_op << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "alu_src= " << debug_dout_t.alu_src << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "rs1= " << debug_dout_t.rs1 << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "rs2= " << debug_dout_t.rs2 << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "dest_reg= " << debug_dout_t.dest_reg << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "imm_u= " << debug_dout_t.imm_u << endl);
            DPRINT(endl);

            for (int i = 0; i < REG_NUM;) {
                DPRINT(endl);
                for (int j = 0; j < 8; j++) {
                    int r = regfile[i].to_int();
                    DPRINT(" " << std::right << std::setfill(' ') << std::setw(2) << i << ": 0x" << std::hex << std::left << std::setfill(' ') << std::setw(10) << r << std::dec);
                    i++;
                    if (i == REG_NUM)
                        break;
                }
                DPRINT(endl);
                if (i == REG_NUM)
                    break;
            }
            DPRINT(endl);
            #endif

            wait();

        } // *** ENDOF while(true)
    } // *** ENDOF sc_cthread

    // --- Utility functions.

    // Sign extend UJ insn.
    ac_int < PC_LEN, false > sign_extend_jump(ac_int < 21, false > imm) {
        if (imm[20] == 1) {
			ac_int < 32, false > ext_imm = 4294967295;
            ext_imm.set_slc(0, imm);
            return ext_imm;
        }
        else {
			ac_int < 32, false > ext_imm = imm;
			return ext_imm;
		}
    }

    // Sign extend branch insn.
    ac_int < PC_LEN, false > sign_extend_branch(ac_int < 13, false > imm) {

        if (imm[12] == 1) {
			ac_int < 32, false > ext_imm = 4294967295;
            ext_imm.set_slc(0, imm);
            return ext_imm;
        }
        else {
			ac_int < 32, false > ext_imm = imm;
			return ext_imm;
		}
    }

    // --- End of utility functions.
};

#endif

left_context:
/*	
	@author VLSI Lab, EE dept., Democritus University of Thrace

	@brief 
	Header file for the drim4hls CPU container.
	This module instantiates the stages and interconnects them.

	@note Changes from HL5

		- Use of HLSLibs connections for communication with the rest of the processor.

		- Connection with memories outside of the processor.


*/

#ifndef __DRIM4HLS__H
#define __DRIM4HLS__H

#include "fetch.h"
#include "decode.h"
#include "execute.h"
#include "execute_fp.h"
#include "writeback.h"

#include "drim4hls_datatypes.h"
#include "defines.h"
#include "globals.h"

#include <mc_connections.h>

#pragma hls_design top
SC_MODULE(drim4hls) {
    public:
    // Declaration of clock and reset signals
    sc_in < bool > clk;
    sc_in < bool > rst;

    //End of simulation signal.
    sc_out < bool > CCS_INIT_S1(program_end);

    // Instruction counters
    sc_out < long int > CCS_INIT_S1(icount);
    sc_out < long int > CCS_INIT_S1(j_icount);
    sc_out < long int > CCS_INIT_S1(b_icount);
    sc_out < long int > CCS_INIT_S1(m_icount);
    sc_out < long int > CCS_INIT_S1(o_icount);

    // Inter-stage Channels and ports.
    Connections::Combinational < fe_out_t > CCS_INIT_S1(fe2de_ch);
    Connections::Combinational < de_out_t > CCS_INIT_S1(de2exe_ch);
    Connections::Combinational < de_out_t > CCS_INIT_S1(de2exefp_ch);
    Connections::Combinational < fe_in_t > CCS_INIT_S1(de2fe_ch);
    Connections::Combinational < mem_out_t > CCS_INIT_S1(wb2de_ch); // Writeback loop
    Connections::Combinational < exe_out_t > CCS_INIT_S1(exe2mem_ch);
    Connections::Combinational < exe_out_t > CCS_INIT_S1(exefp2mem_ch);

    Connections::In < imem_out_t > CCS_INIT_S1(imem2de_data);
    Connections::Out < imem_in_t > CCS_INIT_S1(fe2imem_data);

    Connections::In < dmem_out_t > CCS_INIT_S1(dmem2wb_data);
    Connections::Out < dmem_in_t > CCS_INIT_S1(wb2dmem_data);

    // Forwarding
    Connections::Combinational < reg_forward_t > CCS_INIT_S1(fwd_exe_ch);
    Connections::Combinational < reg_forward_t > CCS_INIT_S1(fwd_exefp_ch);

    // Instantiate the modules
    fetch CCS_INIT_S1(fe);
    decode CCS_INIT_S1(dec);
    execute CCS_INIT_S1(exe);
    execute_fp CCS_INIT_S1(exe_fp);

right_context:
    SC_CTOR(drim4hls): clk("clk"),
    rst("rst"),
    program_end("program_end"),
    fe2de_ch("fe2de_ch"),
    de2exe_ch("de2exe_ch"),
    de2exefp_ch("de2exefp_ch"),
    de2fe_ch("de2fe_ch"),
    exe2mem_ch("exe2mem_ch"),
    exefp2mem_ch("exefp2mem_ch"),
    wb2de_ch("wb2de_ch"),
    fwd_exe_ch("fwd_exe_ch"),
    fwd_exefp_ch("fwd_exefp_ch"),
    imem2de_data("imem2de_data"),
    fe2imem_data("fe2imem_data"),
    dmem2wb_data("dmem2wb_data"),
    wb2dmem_data("wb2dmem_data"),
    fe("Fetch"),
    dec("Decode"),
    exe("Execute"),
    exe_fp("Execute FP"),
    wb("Writeback") {
        // FETCH
        fe.clk(clk);
        fe.rst(rst);
        fe.dout(fe2de_ch);
        fe.imem_din(fe2imem_data);
        fe.imem_dout(imem2de_data);
        fe.fetch_din(de2fe_ch);

        // DECODE
        dec.clk(clk);
        dec.rst(rst);
        dec.dout(de2exe_ch);
        dec.dout_fp(de2exefp_ch);
        dec.feed_from_wb(wb2de_ch);
        dec.fetch_din(fe2de_ch);
        dec.fetch_dout(de2fe_ch);
        dec.program_end(program_end);
        dec.fwd_exe(fwd_exe_ch);
        dec.fwd_exefp(fwd_exefp_ch);
        dec.icount(icount);
        dec.j_icount(j_icount);
        dec.b_icount(b_icount);
        dec.m_icount(m_icount);
        dec.o_icount(o_icount);

        // EXE
        exe.clk(clk);
        exe.rst(rst);
        exe.din(de2exe_ch);
        exe.dout(exe2mem_ch);
        exe.fwd_exe(fwd_exe_ch);

        // EXE FP
        exe_fp.clk(clk);
        exe_fp.rst(rst);
        exe_fp.din(de2exefp_ch);
        exe_fp.dout(exefp2mem_ch);
        exe_fp.fwd_exe(fwd_exefp_ch);

        // MEM
        wb.clk(clk);
        wb.rst(rst);
        wb.din(exe2mem_ch);
        wb.din_fp(exefp2mem_ch);
        wb.dout(wb2de_ch);

        wb.dmem_in(wb2dmem_data);
        wb.dmem_out(dmem2wb_data);
    }

};

#endif // end __DRIM4HLS__H

