/*	
	@author VLSI Lab, EE dept., Democritus University of Thrace

	@brief Header file for fetch stage

	@note Changes from HL5
		- Implements the logic only for the fetch part from fedec.hpp.

		- Use of HLSLibs connections for communication with the rest of the processor.

		- Increment program counter based on new stall functionality.


*/

#ifndef __FETCH__H
#define __FETCH__H

#ifndef NDEBUG
    #include <iostream>
    #define DPRINT(msg) std::cout << msg;
#endif


#include "drim4hls_datatypes.h"
#include "defines.h"
#include "globals.h"

#include <mc_connections.h>
#include <ac_int.h>

SC_MODULE(fetch) {
    public:
    // Clock and reset signals
    sc_in < bool > CCS_INIT_S1(clk);
    sc_in < bool > CCS_INIT_S1(rst);
    // Channel ports
    Connections::In < fe_in_t > CCS_INIT_S1(fetch_din);
    Connections::In < imem_out_t > CCS_INIT_S1(imem_dout);
    Connections::Out < imem_in_t > CCS_INIT_S1(imem_din);
    Connections::Out < fe_out_t > CCS_INIT_S1(dout);

    // Trap signals. TODO: not used. Left for future implementations.
    sc_signal < bool > CCS_INIT_S1(trap); //sc_out
    sc_signal < ac_int < LOG2_NUM_CAUSES, false > > CCS_INIT_S1(trap_cause); //sc_out

    // *** Internal variables
    ac_int < PC_LEN, true > pc; // Init. to -4, then before first insn fetch it will be updated to 0.	 
    ac_int < PC_LEN, false > imem_pc; // Used in fetching from instruction memory
	ac_int < PC_LEN, false > pc_tmp; // Init. to -4, then before first insn fetch it will be updated to 0.	 
    // Custom datatypes used for retrieving and sending data through the channels
    imem_in_t imem_in; // Contains data for fetching from the instruction memory
    fe_out_t fe_out; // Contains data for the decode stage
    fe_in_t fetch_in; // Contains data from the decode stage used in incrementing the PC
    imem_out_t imem_out;

    bool redirect;
    bool redirect_tmp;

    ras_data_t ra_stack[RAS_ENTRIES];
    ac_int < RAS_POINTER_SIZE, false > ras_pointer;
    ac_int < RAS_POINTER_SIZE, false > tosp_pointer;

    ac_int < PC_LEN, false > mispredictions;
    ac_int < PC_LEN, false > correct_predictions;
    ac_int < PC_LEN, false > redirect_addr;

	ac_int < DATA_SIZE, false > mem_dout;
    ac_int < ICACHE_LINE, false > imem_data;
    ac_int < XLEN, false > imem_data_offset;

    ac_int < ICACHE_TAG_WIDTH + ICACHE_INDEX_WIDTH + 1, false > icache_buffer_addr[ICACHE_BUFFER_SIZE][ICACHE_WAYS];
    ac_int < ICACHE_LINE, false > icache_buffer_instr[ICACHE_BUFFER_SIZE][ICACHE_WAYS];

    icache_data_t icache_data[ICACHE_ENTRIES][ICACHE_WAYS];
    icache_tag_t icache_tags[ICACHE_ENTRIES][ICACHE_WAYS];
    icache_out_t icache_out;

    icache_data_t cache_data[1][ICACHE_WAYS];
    icache_tag_t cache_tag[1][ICACHE_WAYS];

    btb_data_t btb_data[BTB_ENTRIES];
    btb_out_t btb_out;

    ac_int < ICACHE_TAG_WIDTH, false > tag;
    ac_int < ICACHE_INDEX_WIDTH, false > index;
    ac_int < ICACHE_OFFSET_WIDTH + 1, false> offset;

    ac_int < ICACHE_TAG_WIDTH + ICACHE_INDEX_WIDTH, false> buffer_addr;

    bool freeze;
    bool hit_buffer;
    int position;

    SC_CTOR(fetch): imem_din("imem_din"),
    fetch_din("fetch_din"),
    dout("dout"),
    imem_dout("imem_dout"),
    clk("clk"),
    rst("rst") {
        SC_THREAD(fetch_th);
        sensitive << clk.pos();
        async_reset_signal_is(rst, false);

    }

    void fetch_th(void) {
        FETCH_RST: {
            dout.Reset();
            fetch_din.Reset();
            imem_din.Reset();
            imem_dout.Reset();

            tag = 0;
            index= 0;
            offset = 0;
            position = 0;

            trap = 0;
            trap_cause = NULL_CAUSE;
            imem_in.instr_addr = 0;

			ras_pointer = 0;
			tosp_pointer = 0;

            redirect_addr = 0;
			freeze = false;
			redirect = false;
            //  Init. pc to START_ADDRESS - 4 as on first fetch it will be incremented by
            //  4, thus fetching instruction at address 0
            pc = 0;
            pc_tmp = -4;
            buffer_addr = 0;

            int n = 0;
            int l = 0;
            for (n = 0; n < ICACHE_BUFFER_SIZE; n++) {
                for (l = 0; l < ICACHE_WAYS; l++) {             
				    icache_buffer_addr[n][l] = 0;
				    icache_buffer_instr[n][l] = 0;
				}
			}

			mispredictions = 0;
			correct_predictions = 0;

            wait();
        }
        #pragma hls_pipeline_init_interval 1
        #pragma pipeline_stall_mode flush
        FETCH_BODY: while (true) {
            //sc_assert(sc_time_stamp().to_double() < 1500000);

			// step 1 fetch from memory/cache
            hit_buffer = false;
            fe_out.pc = pc;

            unsigned int aligned_addr = pc >> 2;
            imem_in.instr_addr = aligned_addr;

            ac_int < XLEN, false > addr = aligned_addr;

            tag = addr.slc<ICACHE_TAG_WIDTH>(ICACHE_INDEX_WIDTH + ICACHE_OFFSET_WIDTH);
            index = addr.slc<ICACHE_INDEX_WIDTH>(ICACHE_OFFSET_WIDTH);        
			if (ICACHE_OFFSET_WIDTH) {
                offset = addr.slc<ICACHE_OFFSET_WIDTH>(0);
            }
            else {
				offset = 0;
			}

			buffer_addr.set_slc(0, index);
			buffer_addr.set_slc(ICACHE_INDEX_WIDTH, tag);

			int m = 0;

right_context:
			int k = ICACHE_BUFFER_SIZE - 1;

			for (k; k > 0; k = k - 1) {
				for (m = 0; m < ICACHE_WAYS; m++) {
					icache_buffer_addr[k][m] = icache_buffer_addr[k-1][m];
					icache_buffer_instr[k][m] = icache_buffer_instr[k-1][m]; 
				}                 
			}

			icache_out = icache();

			for (m = 0; m < ICACHE_WAYS; m++) {                 
				icache_buffer_instr[0][m] = cache_data[0][m].data;
				icache_buffer_addr[0][m].set_slc(0, (ac_int <1, false>) cache_tag[0][m].valid);
				icache_buffer_addr[0][m].set_slc(1, index);
				icache_buffer_addr[0][m].set_slc(ICACHE_INDEX_WIDTH + 1, cache_tag[0][m].tag);  
			}

			if (!icache_out.hit) {
				for (n = 0; n < ICACHE_BUFFER_SIZE; n++) {
					for (m = 0; m < ICACHE_WAYS; m++) {                 
						if (icache_buffer_addr[n][m].slc<ICACHE_TAG_WIDTH + ICACHE_INDEX_WIDTH>(1) == buffer_addr && icache_buffer_addr[n][m].slc<1>(0) == 1) {
							icache_out.data = icache_buffer_instr[n][m];
							icache_out.hit = true;
							hit_buffer = true;
						}
					}
				}
			}

            switch (icache_out.hit)
            {
				case CACHE_HIT:
                    imem_data = icache_out.data;

                    imem_data_offset = imem_data.slc<DATA_WIDTH>(offset*DATA_WIDTH);

                    fe_out.instr_data = imem_data_offset;
                    break;
                case CACHE_MISS:

                    imem_din.Push(imem_in);

					imem_out = imem_dout.Pop();

                    imem_data = imem_out.instr_data;
					imem_data_offset = imem_data.slc<DATA_WIDTH>(offset*DATA_WIDTH);
					fe_out.instr_data = imem_data_offset;

					icache_buffer_addr[0][ICACHE_WAYS - 1].set_slc(0, (ac_int <1, false>) 1);
					icache_buffer_addr[0][ICACHE_WAYS - 1].set_slc(1, buffer_addr);
					icache_buffer_instr[0][ICACHE_WAYS - 1] = imem_data;

                    break;
                default:
                    break;
            }

			icache_write();

			//step2 read from backchannel (decode)
			if (position == 1 && !redirect) {
				fetch_in = fetch_din.Pop();
				redirect_addr = fetch_in.address;
			}else {
				position = 1;
			}
			// step3 if instruction correct send it, update btb, ras and get new pc
			if (redirect_addr == pc) {
				btb_write();
				ras_write();				
				btb();
				ras();
				pc = (btb_out.btb_valid || btb_out.ras_valid) ? btb_out.bta : (ac_int < PC_LEN, false >)(pc + 4);
				redirect = false;
				dout.Push(fe_out);
			}else { // step4 if instruction incorrect, redirect
				pc = redirect_addr;
				redirect = true;
			}

			#ifndef __SYNTHESIS__
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "pc= " << pc << endl);
            DPRINT(endl);
            #endif
            wait();

        } // *** ENDOF while(true)
    } // *** ENDOF sc_cthread

    icache_out_t icache () {

        icache_out_t iout;
        icache_tag_t tmp_tag;
        icache_data_t tmp_data;
        iout.data = 0;
        iout.hit = false;

		int i = 0;
        int j = 0;

        for (i = 0; i < ICACHE_WAYS; i++) {
            cache_tag[0][i] = icache_tags[index][i];
            cache_data[0][i] = icache_data[index][i];

            if ((tag == cache_tag[0][i].tag) && (cache_tag[0][i].valid)) {

                tmp_data = cache_data[0][i];
                tmp_tag = cache_tag[0][i];
                iout.hit = true;
                j = i;

            }

		}

		for (i = ICACHE_WAYS - 1; i > 0; i--) {
			if (iout.hit && i <= j) {
				cache_data[0][i] = cache_data[0][i-1];
				cache_tag[0][i] = cache_tag[0][i-1];
			}

		}

        if (iout.hit) {

            cache_data[0][0] = tmp_data;
            cache_tag[0][0] = tmp_tag;
		}else {
			tmp_data = cache_data[0][ICACHE_WAYS - 1];
		}

        iout.data = tmp_data.data;

        return iout;
    }

    void icache_write () {

        ac_int < ICACHE_INDEX_WIDTH, false > write_index = icache_buffer_addr[1][0].slc<ICACHE_INDEX_WIDTH>(1);
        int i = 0;
        for (i = 0; i < ICACHE_WAYS; i++) {                 

            if (hit_buffer) {
				icache_buffer_instr[0][i] = icache_buffer_instr[1][i];
				icache_buffer_addr[0][i] = icache_buffer_addr[1][i];
			}
				icache_data[write_index][i].data = icache_buffer_instr[1][i];
				icache_tags[write_index][i].valid = icache_buffer_addr[1][i].slc<1>(0);
				icache_tags[write_index][i].tag = icache_buffer_addr[1][i].slc<ICACHE_TAG_WIDTH>(1 + ICACHE_INDEX_WIDTH);
        }


    }

    void btb () {     
        ac_int < BTB_INDEX_WIDTH, false > next_index = pc.slc<BTB_INDEX_WIDTH>(0);
		ac_int < BTB_TAG_WIDTH, false > next_tag = pc.slc<BTB_TAG_WIDTH>(BTB_INDEX_WIDTH);

        if(next_tag == btb_data[next_index].tag && btb_data[next_index].prediction_data > WEAK_NON_TAKEN) {
            btb_out.bta = btb_data[next_index].bta;
            btb_out.btb_valid = true;
        }
        else {
            btb_out.btb_valid = false;
        }
    }

    void btb_write () {
		ac_int < PC_LEN, false > update_pc = fetch_in.pc;
		ac_int < BTB_INDEX_WIDTH, false > index = update_pc.slc<BTB_INDEX_WIDTH>(0);
		ac_int < BTB_TAG_WIDTH, false > tag = update_pc.slc<BTB_TAG_WIDTH>(BTB_INDEX_WIDTH);

		btb_data_t data = btb_data[index];
        //check if tag or branch target address differ in branch target buffer
        if (fetch_in.btb_update) {
            if(tag != data.tag || fetch_in.bta != data.bta) {
                btb_data[index].tag = tag;
                btb_data[index].bta = fetch_in.bta;
                btb_data[index].prediction_data = WEAK_NON_TAKEN;
                if (fetch_in.branch_taken) {
					mispredictions++;
				}    

            }else if (fetch_in.branch_taken && btb_data[index].prediction_data < STRONG_TAKEN){
                btb_data[index].prediction_data = btb_data[index].prediction_data + 1;
                if(btb_data[index].prediction_data > WEAK_NON_TAKEN + 1) {
					correct_predictions++;
				}else {
					mispredictions++;
				}
            }else if (!fetch_in.branch_taken && btb_data[index].prediction_data > 0) {
                btb_data[index].prediction_data = btb_data[index].prediction_data - 1;
                if(btb_data[index].prediction_data > WEAK_NON_TAKEN-1) {
					mispredictions++;
				}else {
					correct_predictions++;
				}

            }else {
				correct_predictions++;
			}
        }
	}

	void ras() {

		if (imem_data_offset.slc<5>(2) == OPC_JALR && ra_stack[ras_pointer].valid) {
			//ras_pointer = ras_pointer - 1;
			btb_out.ras_valid = true;
			btb_out.bta = ra_stack[ras_pointer].pc;
			ra_stack[ras_pointer].valid = false;
			tosp_pointer = tosp_pointer - 1;
			ras_pointer = tosp_pointer - 1;
		}else {
			btb_out.ras_valid = false;
		}
	}

	void ras_write() {
		if (fetch_in.ras_update) {
			ra_stack[tosp_pointer].pc = fetch_in.pc + 4;
			ra_stack[tosp_pointer].valid = true;
			tosp_pointer = tosp_pointer + 1;
			ras_pointer = tosp_pointer - 1;
		}
	}
};

#endif

left_context:
/*	
	@author VLSI Lab, EE dept., Democritus University of Thrace

	@brief Header file for writeback stage.

	@note Changes from HL5

		- Use of HLSLibs connections for communication with the rest of the processor.

		- Memory is outside of the processor

*/

#ifndef __WRITEBACK__H
#define __WRITEBACK__H

#ifndef __SYNTHESIS__
    #include <sstream>
#endif

#ifndef NDEBUG
    #include <iostream>
    #define DPRINT(msg) std::cout << msg;
#endif


#include "drim4hls_datatypes.h"
#include "defines.h"
#include "globals.h"

#include <mc_connections.h>
#include <ac_int.h>

SC_MODULE(writeback) {
    #ifndef __SYNTHESIS__
    struct writeback_out // TODO: fix all sizes
    {
        //
        // Member declarations.
        //		
        unsigned int aligned_address;
        sc_uint < XLEN > load_data;
        sc_uint < XLEN > store_data;
        std::string load;
        std::string store;

    }
    writeback_out_t;
    #endif

    // FlexChannel initiators
    Connections::In < exe_out_t > CCS_INIT_S1(din);
    Connections::In < exe_out_t > CCS_INIT_S1(din_fp);
    Connections::In < dmem_out_t > CCS_INIT_S1(dmem_out);

    Connections::Out < mem_out_t > CCS_INIT_S1(dout);
    Connections::Out < dmem_in_t > CCS_INIT_S1(dmem_in);

    // Clock and reset signals
    sc_in < bool > CCS_INIT_S1(clk);
    sc_in < bool > CCS_INIT_S1(rst);

    // Member variables
    exe_out_t input;
    exe_out_t input_temp;
    dmem_in_t dmem_dout;
    dmem_out_t dmem_din;
    mem_out_t output;

    ac_int < DATA_SIZE, false > mem_dout;
    ac_int < DCACHE_LINE, false > dmem_data;
    ac_int < XLEN, false > dmem_data_offset;

    dcache_data_t dcache_data[DCACHE_ENTRIES][DCACHE_WAYS];
    dcache_tag_t dcache_tags[DCACHE_ENTRIES][DCACHE_WAYS];
    dcache_out_t dcache_out;

    dcache_data_t cache_data[1][DCACHE_WAYS];
    dcache_tag_t cache_tag[1][DCACHE_WAYS];

    ac_int < DCACHE_TAG_WIDTH, false > tag;
    ac_int < DCACHE_INDEX_WIDTH, false > index;
    ac_int < DCACHE_OFFSET_WIDTH + 1, false> offset;

    bool freeze;
    // Constructor
    SC_CTOR(writeback): din("din"), dout("dout"), dmem_in("dmem_in"), dmem_out("dmem_out"), clk("clk"), rst("rst") {
        SC_THREAD(writeback_th);
        sensitive << clk.pos();
        async_reset_signal_is(rst, false);
    }

    void writeback_th(void) {
        WRITEBACK_RST: {
            din.Reset();
            din_fp.Reset();
            dmem_out.Reset();

            dout.Reset();
            dmem_in.Reset();
            // Write dummy data to decode feedback.
            output.regfile_address = 0;
            output.regfile_data = 0;
            output.regwrite = 0;
            output.tag = 0;

			dcache_out.data = 0;
            dcache_out.hit = false;

            dmem_data = 0;
            dmem_data_offset = 0;
            mem_dout = 0;

            tag = 0;
            index = 0;
            offset = 0;

			freeze = false;

        }

        #pragma hls_pipeline_init_interval 1
        #pragma pipeline_stall_mode flush
        WRITEBACK_BODY: while (true) {

            // Get
            freeze = false;
            while (!freeze) {
				if (din.PopNB(input_temp)){
					input = input_temp;
					freeze = true;
				}

				if (din_fp.PopNB(input_temp)){
					input = input_temp;
					freeze = true;
				}
			}

            #ifndef __SYNTHESIS__
                writeback_out_t.aligned_address = 0;
                writeback_out_t.load_data = 0;
                writeback_out_t.store_data = 0;
                writeback_out_t.load = "NO_LOAD";
                writeback_out_t.store = "NO_STORE";
            #endif

            // Compute
            // *** Memory access.
			dmem_data = 0;
			dmem_data_offset = 0;
            // WARNING: only supporting aligned memory accesses
            // Preprocess address

            unsigned int aligned_address = input.alu_res.to_uint();
            ac_int< 5, false> byte_index = (ac_int< 5, false>)((aligned_address & 0x3) << 3);
            ac_int< 5, false> halfword_index = (ac_int< 5, false>)((aligned_address & 0x2) << 3);

            aligned_address = aligned_address >> 2;
            ac_int < BYTE, false > db = (ac_int < BYTE, false >) 0;
            ac_int < 2 * BYTE, false > dh = (ac_int < 2 * BYTE, false >) 0;
            ac_int < XLEN, false > dw = (ac_int < XLEN, false >) 0;

            dmem_dout.data_addr = aligned_address;

            dmem_dout.read_en = false;
            dmem_dout.write_en = false;

            ac_int < XLEN, false > addr = aligned_address;

            tag = addr.slc<DCACHE_TAG_WIDTH>(DCACHE_INDEX_WIDTH + DCACHE_OFFSET_WIDTH);
            index = addr.slc<DCACHE_INDEX_WIDTH>(DCACHE_OFFSET_WIDTH);
            if (DCACHE_OFFSET_WIDTH) {
                offset = addr.slc<DCACHE_OFFSET_WIDTH>(0);
            }
            else {
				offset = 0;
			}
           //unsigned int max_offset = 1 << DCACHE_OFFSET_WIDTH;

            #ifndef __SYNTHESIS__
            if (sc_uint < 3 > (input.ld) != NO_LOAD || sc_uint < 2 > (input.st) != NO_STORE) {
                if (input.mem_datain.to_uint() == 0x11111111 ||
                    input.mem_datain.to_uint() == 0x22222222 ||
                    input.mem_datain.to_uint() == 0x11223344 ||
                    input.mem_datain.to_uint() == 0x88776655 ||
                    input.mem_datain.to_uint() == 0x12345678 ||
                    input.mem_datain.to_uint() == 0x87654321) {
                    std::stringstream stm;
                    stm << hex << "D$ access here2 -> 0x" << aligned_address << ". Value: " << input.mem_datain.to_uint() << std::endl;
                }
                //sc_assert(aligned_address < DCACHE_SIZE);
            }
            #endif

			if ((input.ld != NO_LOAD || input.st != NO_STORE)) { // a load is requested
                dcache_out = dcache();

                switch (dcache_out.hit)
                {
                case CACHE_HIT:
                    dmem_data = dcache_out.data;
                    dmem_data_offset = dmem_data.slc<DATA_WIDTH>(offset*DATA_WIDTH);

                    if (cache_tag[0][0].dirty && input.st != NO_STORE && cache_tag[0][0].tag != tag) {
                        dmem_dout.write_en = true;
                        dmem_dout.data_in = dcache_out.data;
                        if (DCACHE_OFFSET_WIDTH) {
							dmem_dout.write_addr = 0;
						}
						dmem_dout.write_addr.set_slc(DCACHE_OFFSET_WIDTH, index);
						dmem_dout.write_addr.set_slc(DCACHE_INDEX_WIDTH + DCACHE_OFFSET_WIDTH, cache_tag[0][0].tag);

                        dmem_in.Push(dmem_dout);
                    }

                    break;
                case CACHE_MISS:

                    dmem_dout.read_en = true;
                    if (cache_tag[0][DCACHE_WAYS - 1].dirty && cache_tag[0][DCACHE_WAYS - 1].tag != tag) {
                        dmem_dout.write_en = true;
                        dmem_dout.data_in = dcache_out.data;

                        if (DCACHE_OFFSET_WIDTH) {
							dmem_dout.write_addr = 0;
						}
						dmem_dout.write_addr.set_slc(DCACHE_OFFSET_WIDTH, index);
						dmem_dout.write_addr.set_slc(DCACHE_INDEX_WIDTH + DCACHE_OFFSET_WIDTH, cache_tag[0][DCACHE_WAYS - 1].tag);
                    }

                    dmem_in.Push(dmem_dout);

                    dmem_din = dmem_out.Pop();
                    dmem_data = dmem_din.data_out;
					dmem_data_offset = dmem_data.slc<DATA_WIDTH>(offset*DATA_WIDTH);

                    dmem_dout.data_in = cache_data[0][DCACHE_WAYS - 1].data;

                    if (input.ld != NO_LOAD) {
						cache_data[0][DCACHE_WAYS - 1].data = dmem_data;
					}

                    break;
                default:
                    break;
                }
            }

            if (input.ld != NO_LOAD) { // a load is requested

                switch (input.ld) { // LOAD
                case LB_LOAD:                    
                    db.set_slc(0, dmem_data_offset.slc<BYTE>(byte_index));
                    mem_dout = ext_sign_byte(db);

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "LB_LOAD";
                    #endif

                    break;
                case LH_LOAD:
                    dh.set_slc(0, dmem_data_offset.slc< 2*BYTE >(halfword_index));
                    mem_dout = ext_sign_halfword(dh);

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "LH_LOAD";
                    #endif

                    break;
                case LW_LOAD:
                    dw = dmem_data_offset;
                    mem_dout = dw;

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "LW_LOAD";
                    #endif

                    break;
                case LBU_LOAD:
                    db.set_slc(0, dmem_data_offset.slc<BYTE>(byte_index));
                    mem_dout = ext_unsign_byte(db);

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "LBU_LOAD";
                    #endif

                    break;
                case LHU_LOAD:
                    dh.set_slc(0, dmem_data_offset.slc< 2 * BYTE >(halfword_index));
                    mem_dout = ext_unsign_halfword(dh);

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "LHU_LOAD";
                    #endif

                    break;
                default:

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "NO_LOAD";
                    #endif

                    break; // NO_LOAD
                }
            } else if (input.st != NO_STORE) { // a store is requested

                switch (input.st) { // STORE
                case SB_STORE: // store 8 bits of rs2

					db.set_slc(0, (ac_int < BYTE, false >) input.mem_datain.slc<BYTE>(0));
					dmem_data_offset.set_slc(byte_index, (ac_int < BYTE, false >) db);

                    #ifndef __SYNTHESIS__
                    writeback_out_t.store_data = db;
                    writeback_out_t.store = "SB_STORE";
                    #endif

                    break;
                case SH_STORE: // store 16 bits of rs2

					dh.set_slc(0, input.mem_datain.slc<2*BYTE>(0));
					dmem_data_offset.set_slc(byte_index, dh);

                    #ifndef __SYNTHESIS__
                    writeback_out_t.store_data = dh;
                    writeback_out_t.store = "SH_STORE";
                    #endif

                    break;
                case SW_STORE: // store rs2
                    dw = input.mem_datain;
                    dmem_data_offset = dw;

                    #ifndef __SYNTHESIS__
                    writeback_out_t.store_data = dw;
                    writeback_out_t.store = "SW_STORE";
                    #endif

					break;
                default:

                    #ifndef __SYNTHESIS__
                    writeback_out_t.store = "NO_STORE";
                    #endif

                    break; // NO_STORE
                }
				dmem_data.set_slc(offset*DATA_WIDTH, dmem_data_offset);

                if (dcache_out.hit) {
                    dmem_dout.data_in = cache_data[0][0].data;
                    cache_data[0][0].data = dmem_data;
                }else {
                    dmem_dout.data_in = cache_data[0][DCACHE_WAYS - 1].data;
                    cache_data[0][DCACHE_WAYS - 1].data = dmem_data;
                }

            }

            bool ld_st_write = (input.st != NO_STORE) ? false : true;

			if ((input.st != NO_STORE || input.ld != NO_LOAD)) {
				dcache_write(ld_st_write, dcache_out.hit);
			}

            // *** END of memory access.

            /* Writeback */
            output.regwrite = input.regwrite;
            output.regfile_address = input.dest_reg;
            output.regfile_data = (input.memtoreg[0] == 1) ? mem_dout : input.alu_res;
            output.tag = input.tag;
            output.pc = input.pc;
            output.dest_freg = input.dest_freg;

            // Put
		    dout.Push(output);

            #ifndef __SYNTHESIS__
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "load= " << writeback_out_t.load << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "store= " << writeback_out_t.store << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "input.regwrite=" << input.regwrite << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "regwrite=" << output.regwrite << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "aligned_address=" << aligned_address << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "mem_dout=" << mem_dout << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "input.alu_res=" << input.alu_res << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "output.regfile_address=" << output.regfile_address << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "output.regfile_data=" << output.regfile_data << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "input.memtoreg=" << input.memtoreg << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "writeback_out_t.store_data =" << writeback_out_t.store_data  << endl);
            DPRINT(endl);
            #endif
            wait();
        }
    }

    /* Support functions */

    // Sign extend byte read from memory. For LB
    ac_int < XLEN, false > ext_sign_byte(ac_int < BYTE, false > read_data) {
		ac_int <XLEN, false> extended = 0;
		if (read_data[7] == 1) {
			extended.set_slc(0, read_data);
			extended.set_slc(BYTE, (ac_int < BYTE * 3, false >) 16777216);
		}
		else {
			extended.set_slc(0, read_data);
			extended.set_slc(BYTE, (ac_int < BYTE * 3, false >) 0);		
		}
		return extended;
    }

    // Zero extend byte read from memory. For LBU
    ac_int < XLEN, false > ext_unsign_byte(ac_int < BYTE, false > read_data) {
		ac_int <XLEN, false> extended = 0;
		extended.set_slc(0, read_data);
		extended.set_slc(BYTE, (ac_int < BYTE * 3, false >) 0);
		return extended;        
    }

    // Sign extend half-word read from memory. For LH
    ac_int < XLEN, false > ext_sign_halfword(ac_int < BYTE * 2, false > read_data) {
		ac_int <XLEN, false> extended = 0;

        if (read_data[15] == 1) {
			extended.set_slc(0, read_data);
			extended.set_slc(2*BYTE, (ac_int < BYTE * 2, false >) 65535);
        }
        else {
			extended.set_slc(0, read_data);
			extended.set_slc(2*BYTE, (ac_int < BYTE * 2, false >) 0);
        }
        return extended;
    }

    // Zero extend half-word read from memory. For LHU
    ac_int < XLEN, false > ext_unsign_halfword(ac_int < BYTE * 2, false > read_data) {
		ac_int <XLEN, false> extended = 0;
		extended.set_slc(0, read_data);
		extended.set_slc(2*BYTE, (ac_int < BYTE * 2, false >) 0);
		return extended;
    }

    dcache_out_t dcache () {

        dcache_out_t dout;
        dcache_tag_t tmp_tag;
        dcache_data_t tmp_data;
        dout.data = 0;
        dout.hit = false;

right_context:
        int j = 0;

        for (i = 0; i < DCACHE_WAYS; i++) {
            cache_tag[0][i] = dcache_tags[index][i];
            cache_data[0][i] = dcache_data[index][i];

            if ((tag == cache_tag[0][i].tag) && (cache_tag[0][i].valid)) {

                tmp_data = cache_data[0][i];
                tmp_tag = cache_tag[0][i];
                dout.hit = true;
                j = i;

            }

		}

		for (i = DCACHE_WAYS - 1; i > 0; i--) {
			if (dout.hit && i <= j) {
				cache_data[0][i] = cache_data[0][i-1];
				cache_tag[0][i] = cache_tag[0][i-1];
			}

		}

        if (dout.hit) {

            cache_data[0][0] = tmp_data;
            cache_tag[0][0] = tmp_tag;
		}else {
			tmp_data = cache_data[0][DCACHE_WAYS - 1];
		}

        dout.data = tmp_data.data;

        return dout;
    }

    void dcache_write (bool load, bool hit) {

		unsigned int bank = 0;
        if (!hit) {
            bank = DCACHE_WAYS - 1;
        }


        if (cache_tag[0][bank].dirty && cache_tag[0][bank].tag != tag && !(load && hit)) {

            cache_tag[0][bank].tag = tag;
            cache_tag[0][bank].valid = true;

        } else if (!(load && hit)) { 

            cache_tag[0][bank].tag = tag;
            cache_tag[0][bank].valid = true;
        }

        if (!load) {
            cache_tag[0][bank].dirty = true;
        }else if (!hit){
            cache_tag[0][bank].dirty = false;
        }

        int i = 0;
        for (i = 0; i < DCACHE_WAYS; i++) {                 
            dcache_data[index][i] = cache_data[0][i];
            dcache_tags[index][i] = cache_tag[0][i];

        }      

    }

};

#endif

left_context:
/*	
	@author VLSI Lab, EE dept., Democritus University of Thrace

	@brief Header file for decode stage

	@note Changes from HL5
		- Implements the logic only for the decode part from fedec.hpp.

		- Use of HLSLibs connections for communication with the rest of the processor.

		- Stall mechanism manages data dependencies, dynamic load/write memory stalls
		  and change of program direction.


*/

#ifndef __DEC__H
#define __DEC__H

#ifndef NDEBUG
    #include <iostream>
    #define DPRINT(msg) std::cout << msg;
#endif

#include "drim4hls_datatypes.h"
#include "defines.h"
#include "globals.h"

#include <mc_connections.h>

SC_MODULE(decode) {
    public:
    // Clock and reset signals
    sc_in < bool > CCS_INIT_S1(clk);
    sc_in < bool > CCS_INIT_S1(rst);
    // FlexChannel initiators
    Connections::Out < de_out_t > CCS_INIT_S1(dout);
    Connections::Out < fe_in_t > CCS_INIT_S1(fetch_dout);
    Connections::In < mem_out_t > CCS_INIT_S1(feed_from_wb);
    Connections::In < fe_out_t > CCS_INIT_S1(fetch_din);
    Connections::In < reg_forward_t > CCS_INIT_S1(fwd_exe);

    // End of simulation signal.
    sc_out < bool > CCS_INIT_S1(program_end);

    // Instruction counters
    sc_out < long int > CCS_INIT_S1(icount);
    sc_out < long int > CCS_INIT_S1(j_icount);
    sc_out < long int > CCS_INIT_S1(b_icount);
    sc_out < long int > CCS_INIT_S1(m_icount);
    sc_out < long int > CCS_INIT_S1(o_icount);

    bool jump;
    bool branch;
    // Trap signals. TODO: not used. Left for future implementations.
    sc_signal < bool > CCS_INIT_S1(trap); //sc_out
    sc_signal < ac_int < LOG2_NUM_CAUSES, false > > CCS_INIT_S1(trap_cause); //sc_out

    bool freeze;
    // Flushes current instruction in order to sychronize processor with a
    // change of direction in the execution
    bool flush;

    bool forward_success_rs1;
    bool forward_success_rs2;

    bool load_instruction;
    sc_int < PC_LEN > load_pc;

    sc_uint < INSN_LEN > insn; // Contains full instruction fetched from IMEM. Used in decoding.
    sc_int < PC_LEN > pc; // Contains PC for the current instruction that is decoded   
    // NB. x0 is included in this regfile so it is not a real hardcoded 0
    // constant. The writeback section of fedec has a guard fro writes on
    // x0. For double protection, some instructions that want to write into
    // x0 will have their regwrite signal forced to false.
    sc_uint < XLEN > regfile[REG_NUM];
    // Keeps track of in-flight instructions that are going to overwrite a
    // register. Implements a primitive stall mechanism for RAW hazards.
    sc_uint < XLEN + 1 > sentinel[REG_NUM];

    sc_uint < TAG_WIDTH > tag;
    // Stalls processor and sends a nop operation to the execute stage
    sc_uint < OPCODE_SIZE > opcode;

    int position;
    // Member variables (DECODE)
    de_in_t self_feed; // Contains branch and jump data		 
    mem_out_t feedinput; // Contains data from writeback stage
    mem_out_t feedinput_tmp; // Contains data from writeback stage
    de_out_t output; // Contains data for the execute stage
    fe_out_t input; // Contains data from the fetch stage
    fe_in_t fetch_out; // Contains data for the fetch stage about processor stalls

    reg_forward_t fwd;
    reg_forward_t temp_fwd;

    fe_out_t fetch_in; // Buffer for the data coming from the fetch stage

    unsigned int imem_data; // Contains instruction data

	bool freeze_tmp;
	sc_uint< 32 > addr_tmp;
	sc_uint< 5 > zero_reg_addr;

    bool flush_next;
    bool new_instr;
    int position_fwd;
    int position_wb;

    sc_uint < DCACHE_INDEX_WIDTH > last_ldst_index;
    sc_uint < DCACHE_INDEX_WIDTH > last_ldst_index_temp;
    bool last_ldst_valid;

    SC_CTOR(decode): clk("clk"),
    rst("rst"),
    dout("dout"),
    feed_from_wb("feed_from_wb"),
    fetch_din("fetch_din"),
    fetch_dout("fetch_dout"),
    program_end("program_end"),
    fwd_exe("fwd_exe"),
    icount("icount"),
    j_icount("j_icount"),
    b_icount("b_icount"),
    m_icount("m_icount"),
    o_icount("o_icount") {

        SC_THREAD(decode_th);
        sensitive << clk.pos();
        async_reset_signal_is(rst, false);

    }

    #ifndef __SYNTHESIS__
    //for debugging purposes
    struct debug_dout { //
        // Member declarations.
        //
        std::string regwrite;
        std::string memtoreg;
        std::string ld;
        std::string st;
        std::string alu_op;
        std::string alu_src;
        bool rs1_forward;
        bool rs2_forward;
        bool branch_taken;
        sc_uint < XLEN > rs1;
        sc_uint < XLEN > rs2;
        std::string dest_reg;
        int pc;
        int aligned_pc;
        sc_uint < XLEN - 12 > imm_u;
        sc_uint < TAG_WIDTH > tag;

    }
    debug_dout_t;
    #endif

    void decode_th(void) {
        DECODE_RST: {
            dout.Reset();
            fetch_din.Reset();
            feed_from_wb.Reset();
            fetch_dout.Reset();
            fwd_exe.Reset();
			//fetch_dout.write(fetch_out);
            // Init. sentinel flags to zero.
            for (int i = 0; i < REG_NUM; i++) {
                sentinel[i] = SENTINEL_INIT;
            }

            // Program has not completed
            program_end.write(false);
            icount.write(0); // any
            j_icount.write(0); // jump
            b_icount.write(0); // branch
            m_icount.write(0); // load, store
            o_icount.write(0); // other

            addr_tmp = 0;
            zero_reg_addr = 0;

            freeze = false;
            flush = false;
	        flush_next = false;
            freeze_tmp = false;

            forward_success_rs1 = false;
            forward_success_rs2 = false;
            position = 0;
            insn = 0;
            branch = false;
            jump = false;
            pc = -4;
            load_instruction = false;
            load_pc = -4;
            new_instr = false;
            position_fwd = 0;
            position_wb = 0;
            fetch_out.address = 0;

			last_ldst_valid = false;
			last_ldst_index = 0;
			last_ldst_index_temp = 0;

            wait();
        }

        #pragma hls_pipeline_init_interval 1
        #pragma pipeline_stall_mode flush
        DECODE_BODY: while (true) {
            // Retrieve data from instruction memory and fetch stage.
            // If processor stalls then just clear the channels from new data.

			if (!freeze) {
				fetch_in = fetch_din.Pop();
				pc = fetch_in.pc;
				imem_data = fetch_in.instr_data;
			}


            if (position_fwd == 1) {
				fwd = fwd_exe.Pop();
			}else {
				position_fwd = 1;
			}

			if (position_wb == 2) {
				feedinput = feed_from_wb.Pop();

				if (feedinput.pc == load_pc && load_instruction) {
                    load_instruction = false;
                }
			}else {
				position_wb++;
			}

            if (feedinput.regwrite == 1 && feedinput.regfile_address != 0) { // Actual writeback.
                    regfile[feedinput.regfile_address] = feedinput.regfile_data; // Overwrite register.

				if ((feedinput.pc == sentinel[feedinput.regfile_address].range(32,1)) && (sentinel[feedinput.regfile_address][0] == 1)) {
					sentinel[feedinput.regfile_address][0] = 0;
				}

            }

            flush_next = false;
            new_instr = false;

            insn = imem_data;

			forward_success_rs1 = false;
            forward_success_rs2 = false;

            new_instr = true;

            #ifndef __SYNTHESIS__
            debug_dout_t.pc = pc;
            #endif

            output.pc = pc;
            fetch_out.pc = pc;
            // Increment some instruction counters
            //opcode = sc_uint < OPCODE_SIZE > (sc_bv < OPCODE_SIZE > (insn.range(6, 2)));
			opcode = insn.range(6, 2);

            if (opcode == OPC_LW || opcode == OPC_SW) {
                // Increment memory instruction counter
				m_icount.write(m_icount.read() + 1);
			}
            else if (opcode == OPC_JAL || opcode == OPC_JALR) {
				// Increment jump instruction counter
                j_icount.write(j_icount.read() + 1);
			} else if (opcode == OPC_BEQ) {
				// Increment branch instruction counter
				b_icount.write(b_icount.read() + 1);
            } else {
				// Increment other instruction counter
                o_icount.write(o_icount.read() + 1);
			}
            icount.write(icount.read() + 1);

            freeze_tmp = false;

           if (insn == 0x0000006f) {
                // jump to yourself (end of program).
                program_end.write(true);
            }

            sc_uint < REG_ADDR > rs1_addr = insn.range(19, 15);
            sc_uint < REG_ADDR > rs2_addr = insn.range(24, 20);


			sc_uint< 32 > rs1_sent_pc = sentinel[rs1_addr].range(32, 1);
			sc_uint < 1 > rs1_sent_valid = sentinel[rs1_addr].range(0, 0);

            if (!fwd.ldst && fwd.pc == rs1_sent_pc && rs1_sent_valid == 1) {
                forward_success_rs1 = true;
                output.rs1 = fwd.regfile_data;
                #ifndef __SYNTHESIS__
                debug_dout_t.rs1 = fwd.regfile_data;
                debug_dout_t.rs1_forward = forward_success_rs1;
                #endif
            } else if (!forward_success_rs1) {

                output.rs1 = regfile[rs1_addr];
                #ifndef __SYNTHESIS__
                debug_dout_t.rs1 = regfile[rs1_addr];
                debug_dout_t.rs1_forward = forward_success_rs1;
                #endif

            }

            sc_uint < 32 > rs2_sent_pc = sentinel[rs2_addr].range(32, 1);
			sc_uint < 1 > rs2_sent_valid = sentinel[rs2_addr].range(0, 0);

            if (!fwd.ldst && fwd.pc == rs2_sent_pc && rs2_sent_valid == 1) {
                forward_success_rs2 = true;
                output.rs2 = fwd.regfile_data;
				#ifndef __SYNTHESIS__
                debug_dout_t.rs2 = fwd.regfile_data;
                debug_dout_t.rs2_forward = forward_success_rs2;
                #endif

            } else if (!forward_success_rs2) {

                output.rs2 = regfile[rs2_addr];
                #ifndef __SYNTHESIS__
                debug_dout_t.rs2 = regfile[rs2_addr];
                debug_dout_t.rs2_forward = forward_success_rs2;
                #endif


            }

            // *** Feedback to fetch data computation and put() section.
            // -- Address sign extensions.
            sc_uint < 21 > immjal_tmp = ((sc_uint<1>)insn.range(31, 31), (sc_uint<8>)insn.range(19, 12), (sc_uint<1>)insn.range(20, 20), (sc_uint<10>)insn.range(30, 21), (sc_uint<1>)(0));
            sc_uint < 13 > immbranch_tmp = ((sc_uint<1>)insn.range(31, 31), (sc_uint<1>)insn.range(7, 7), (sc_uint<6>)insn.range(30, 25), (sc_uint<4>)insn.range(11, 8), (sc_uint<1>)(0));

            self_feed.branch_address = sign_extend_branch(immbranch_tmp + pc);
            // -- Jump.
            fetch_out.branch_taken = false;
            fetch_out.btb_update = false;
            fetch_out.ras_update = false;
            fetch_out.address = pc + 4;
            jump = false;

            if (insn.range(6, 2) == OPC_JAL) {
                self_feed.jump_address = sign_extend_jump(immjal_tmp + pc);
                jump = true;
                fetch_out.ras_update = true;
                fetch_out.bta = self_feed.jump_address;
                fetch_out.address = self_feed.jump_address;
            } else if (insn.range(6, 2) == OPC_JALR) {
                sc_uint < PC_LEN > extended;
                if (insn[31] == 0)
                    extended = 0;
                else
                    extended = 4294967295;

                extended.range(11, 0) = insn.range(31, 20);
                self_feed.jump_address = extended + output.rs1;
                self_feed.jump_address[0] = 0;

                jump = true;

                fetch_out.bta = self_feed.jump_address;
                fetch_out.address = self_feed.jump_address;
            }

            // -- Branch circuitry.
            branch = false;
            if (insn.range(6, 2) == OPC_BEQ) { // BEQ,BNE, BLT, BGE, BLTU, BGEU
				fetch_out.btb_update = true;
				fetch_out.bta = self_feed.branch_address;
                switch (insn.range(14, 12)) {
                case FUNCT3_BEQ:
                    if (output.rs1 == output.rs2) {
						branch = true; // BEQ taken.
						fetch_out.branch_taken = true;
						fetch_out.address = self_feed.branch_address;
						#ifndef __SYNTHESIS__
						debug_dout_t.branch_taken = true;
						#endif
					}

                    break;
                case FUNCT3_BNE:
                    if (output.rs1 != output.rs2) {
						branch = true; //BNE taken.
						fetch_out.branch_taken = true;
                        fetch_out.address = self_feed.branch_address;
                        #ifndef __SYNTHESIS__
                        debug_dout_t.branch_taken = true;
                        #endif
                    }
                    break;
                case FUNCT3_BLT:
                    if (output.rs1 < output.rs2) {
						branch = true; // BLT taken
						fetch_out.branch_taken = true;
						fetch_out.address = self_feed.branch_address;
                        #ifndef __SYNTHESIS__
                        debug_dout_t.branch_taken = true;
                        #endif
                    }
                    break;
                case FUNCT3_BGE:
                    if (output.rs1 >= output.rs2) {
						branch = true; // BGE taken.
						fetch_out.branch_taken = true;
						fetch_out.address = self_feed.branch_address;
                        #ifndef __SYNTHESIS__
                        debug_dout_t.branch_taken = true;
                        #endif
                    }
                    break;
                case FUNCT3_BLTU:
                    if (output.rs1 < output.rs2) {
						branch = true; // BLTU taken.
						fetch_out.branch_taken = true;
						fetch_out.address = self_feed.branch_address;
                        #ifndef __SYNTHESIS__
                        debug_dout_t.branch_taken = true;
                        #endif
                    }
                    break;
                case FUNCT3_BGEU:
                    if (output.rs1 >= output.rs2) {
						branch = true; // BGEU taken.
						fetch_out.branch_taken = true;
						fetch_out.address = self_feed.branch_address;
                        #ifndef __SYNTHESIS__
                        debug_dout_t.branch_taken = true;
                        #endif
                    }
                    break;
                default:
                    branch = false; // default to not taken.
                    #ifndef __SYNTHESIS__
                    debug_dout_t.branch_taken = false;
                    #endif
                    break;
                }
            }
            // -- All data for feedback path to fetch is ready now. Do put(): in this version it saved data in self_feed.
            // *** END of feedback to fetch data computation and put() section.

            // *** Propagations: rd, immediates sign extensions.
            output.dest_reg = insn.range(11 , 7);
            // RD field of insn.
            output.imm_u = insn.range(31, 12); // This field is then used in the execute stage not only as immU field but to obtain several subfields used by non U-type instructions.

            #ifndef __SYNTHESIS__
            debug_dout_t.dest_reg = std::to_string(insn.range(11 , 7).to_int());
            debug_dout_t.imm_u = insn.range(31, 12);
            #endif
            // *** END of RD propagation and immediates sign extensions.

            // *** Control word generation.
            switch (insn.range(6, 2)) { // Opcode's 2 LSBs have been trimmed to save area.

            case OPC_LUI:
                output.alu_op = ALUOP_LUI;
                output.alu_src = ALUSRC_IMM_U;
                output.regwrite = 1;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.memtoreg = 0;
                trap = 0;
                trap_cause = NULL_CAUSE;

                #ifndef __SYNTHESIS__
                debug_dout_t.alu_op = "ALUOP_LUI";
                debug_dout_t.alu_src = "ALUSRC_IMM_U";
                debug_dout_t.regwrite = "REGWRITE YES";
                debug_dout_t.ld = "NO LOAD";
                debug_dout_t.st = "NO STORE";
                debug_dout_t.memtoreg = "MEMTOREG YES";
                #endif
                break;

            case OPC_AUIPC:
                output.alu_op = ALUOP_AUIPC;
                output.alu_src = ALUSRC_IMM_U;
                output.regwrite = 1;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.memtoreg = 0;
                trap = 0;
                trap_cause = NULL_CAUSE;

                #ifndef __SYNTHESIS__
                debug_dout_t.alu_op = "ALUOP_AUIPC";
                debug_dout_t.alu_src = "ALUSRC_IMM_U";
                debug_dout_t.regwrite = "REGWRITE YES";
                debug_dout_t.ld = "NO LOAD";
                debug_dout_t.st = "NO STORE";
                debug_dout_t.memtoreg = "MEMTOREG NO";
                #endif
                break;

            case OPC_JAL:
                output.alu_op = ALUOP_JAL;
                output.alu_src = ALUSRC_RS2; // Actually does not use RS2 as it performs "rd = pc + 4"
                output.regwrite = 1;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.memtoreg = 0;
                trap = 0;
                trap_cause = NULL_CAUSE;

                #ifndef __SYNTHESIS__
                debug_dout_t.alu_op = "ALUOP_JAL";
                debug_dout_t.alu_src = "ALUSRC_RS2";
                debug_dout_t.regwrite = "REGWRITE YES";
                debug_dout_t.ld = "NO LOAD";
                debug_dout_t.st = "NO STORE";
                debug_dout_t.memtoreg = "MEMTOREG NO";
                #endif
                break;

            case OPC_JALR: // same as JAL, could optimize
                output.alu_op = ALUOP_JALR;
                output.alu_src = ALUSRC_RS2; // Actually does not use RS2 as it performs "rd = pc + 4"
                output.regwrite = 1;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.memtoreg = 0;
                trap = 0;
                trap_cause = NULL_CAUSE;

                #ifndef __SYNTHESIS__
                debug_dout_t.alu_op = "ALUOP_JALR";
                debug_dout_t.alu_src = "ALUSRC_RS2";
                debug_dout_t.regwrite = "REGWRITE YES";
                debug_dout_t.ld = "NO LOAD";
                debug_dout_t.st = "NO STORE";
                debug_dout_t.memtoreg = "MEMTOREG NO";
                #endif
                break;

            case OPC_BEQ: // Branch instructions: BEQ, BNE, BLT, BGE, BLTU, BGEU
                output.alu_op = ALUOP_NULL;
                output.alu_src = ALUSRC_RS2;
                output.regwrite = 0;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.memtoreg = 0;
                trap = 0;
                trap_cause = NULL_CAUSE;

                #ifndef __SYNTHESIS__
                debug_dout_t.alu_op = "ALUOP_BEQ";
                debug_dout_t.alu_src = "ALUSRC_RS2";
                debug_dout_t.regwrite = "REGWRITE NO";
                debug_dout_t.ld = "NO LOAD";
                debug_dout_t.st = "NO STORE";
                debug_dout_t.memtoreg = "MEMTOREG NO";
                #endif
                break;

            case OPC_LW:
                switch (insn.range(14, 12)) {
                case FUNCT3_LB:
                    output.ld = LB_LOAD;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.ld = "LB_LOAD";
                    #endif
                    break;
                case FUNCT3_LH:
                    output.ld = LH_LOAD;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.ld = "LH_LOAD";
                    #endif
                    break;
                case FUNCT3_LW:
                    output.ld = LW_LOAD;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.ld = "LW_LOAD";
                    #endif
                    break;
                case FUNCT3_LBU:
                    output.ld = LBU_LOAD;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.ld = "LBU_LOAD";
                    #endif
                    break;
                case FUNCT3_LHU:
                    output.ld = LHU_LOAD;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.ld = "LHU_LOAD";
                    #endif
                    break;
                default:
                    output.ld = NO_LOAD;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.ld = "NO_LOAD";
                    #endif
                    SC_REPORT_ERROR(sc_object::name(), "Unimplemented LOAD instruction");
                    break;
                }
                output.alu_op = ALUOP_ADD;
                output.alu_src = ALUSRC_IMM_I;
                output.regwrite = 1;
                output.st = NO_STORE;
                output.memtoreg = 1;
                trap = 0;
                trap_cause = NULL_CAUSE;

                #ifndef __SYNTHESIS__
                debug_dout_t.alu_op = "ALUOP_ADD";
                debug_dout_t.alu_src = "ALUSRC_IMM_I";
                debug_dout_t.regwrite = "REGWRITE YES";
                debug_dout_t.st = "NO_STORE";
                debug_dout_t.memtoreg = "MEMTOREG YES";
                #endif
                break;

            case OPC_SW:
                switch (insn.range(14, 12)) {
                case FUNCT3_SB:
                    output.st = SB_STORE;
                    #ifndef __SYNTHESIS__
                    debug_dout_t.st = "SB_STORE";
                    #endif
                    break;
                case FUNCT3_SH:
                    output.st = SH_STORE;
                    #ifndef __SYNTHESIS__
                    debug_dout_t.st = "SH_STORE";
                    #endif
                    break;
                case FUNCT3_SW:
                    output.st = SW_STORE;
                    #ifndef __SYNTHESIS__
                    debug_dout_t.st = "SW_STORE";
                    #endif
                    break;
                default:
                    output.st = NO_STORE;
                    #ifndef __SYNTHESIS__
                    debug_dout_t.st = "NO_STORE";
                    #endif
                    SC_REPORT_ERROR(sc_object::name(), "Unimplemented STORE instruction");
                    break;
                }
                output.alu_op = ALUOP_ADD;
                output.alu_src = ALUSRC_IMM_S;
                output.regwrite = 0;
                output.ld = NO_LOAD;
                output.memtoreg = 0;
                trap = 0;
                trap_cause = NULL_CAUSE;

                #ifndef __SYNTHESIS__
                debug_dout_t.alu_op = "ALUOP_ADD";
                debug_dout_t.alu_src = "ALUSRC_IMM_S";
                debug_dout_t.regwrite = "REGWRITE NO";
                debug_dout_t.ld = "NO_LOAD";
                debug_dout_t.memtoreg = "MEMTOREG NO";
                #endif
                break;

            case OPC_ADDI: // OP-IMM instructions (arithmetic and logical operations on immediates): ADDI, SLTI, SLTIU, XORI, ORI, ANDI, SLLI, SRLI, SRAI

                if (insn.range(31 ,25) == FUNCT7_SRAI && insn.range(14, 12) == FUNCT3_SRAI) {
                    output.alu_op = ALUOP_SRAI;
                    output.alu_src = ALUSRC_IMM_U;

                    #ifndef __SYNTHESIS__

right_context:
                    output.alu_src = ALUSRC_IMM_U;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.alu_op = "ALUOP_SLLI";
                    debug_dout_t.alu_src = "ALUSRC_IMM_U";
                    #endif
                } else if (insn.range(31 ,25) == FUNCT7_SRLI && insn.range(14, 12) == FUNCT3_SRLI) {
                    output.alu_op = ALUOP_SRLI;
                    output.alu_src = ALUSRC_IMM_U;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.alu_op = "ALUOP_SRLI";
                    debug_dout_t.alu_src = "ALUSRC_IMM_U";
                    #endif
                } else {
                    output.alu_src = ALUSRC_IMM_I;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.alu_src = "ALUSRC_IMM_I";
                    #endif
                    switch (insn.range(14, 12)) {
                    case FUNCT3_ADDI:
                        output.alu_op = ALUOP_ADDI;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_ADDI";
                        #endif
                        break;
                    case FUNCT3_SLTI:
                        output.alu_op = ALUOP_SLTI;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_SLTI";
                        #endif
                        break;
                    case FUNCT3_SLTIU:
                        output.alu_op = ALUOP_SLTIU;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_SLTIU";
                        #endif
                        break;
                    case FUNCT3_XORI:
                        output.alu_op = ALUOP_XORI;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_XORI";
                        #endif
                        break;
                    case FUNCT3_ORI:
                        output.alu_op = ALUOP_ORI;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_ORI";
                        #endif
                        break;
                    case FUNCT3_ANDI:
                        output.alu_op = ALUOP_ANDI;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_ANDI";
                        #endif
                        break;
                    default:
                        output.alu_op = ALUOP_NULL;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_NULL";
                        #endif
                        SC_REPORT_ERROR(sc_object::name(), "Unimplemented ALUOP_IMM instruction");
                        break;
                    }
                }
                output.regwrite = 1;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.memtoreg = 0;
                trap = 0;
                trap_cause = NULL_CAUSE;

                #ifndef __SYNTHESIS__
                debug_dout_t.regwrite = "REGWRITE YES";
                debug_dout_t.ld = "NO_LOAD";
                debug_dout_t.st = "NO_STORE";
                debug_dout_t.memtoreg = "MEMTOREG NO";
                #endif
                break;

            case OPC_ADD: // R-type instructions: ADD, SLL, SLT, SLTU, XOR, SRL, OR, AND, SUB, SRA, MUL, MULH, MULHSU, MULHU, DIV, DIVU, REM, REMU.
                output.alu_src = ALUSRC_RS2;
                output.regwrite = 1;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.memtoreg = 0;
                trap = 0;
                trap_cause = NULL_CAUSE;

                #ifndef __SYNTHESIS__
                debug_dout_t.alu_src = "ALUSRC_RS2";
                debug_dout_t.regwrite = "REGWRITE YES";
                debug_dout_t.ld = "NO_LOAD";
                debug_dout_t.st = "NO_STORE";
                debug_dout_t.memtoreg = "REGWRITE NO";
                #endif
                // FUNCT7 switch discriminates between classes of R-type instructions.
                switch (insn.range(31, 25)) {
                case FUNCT7_ADD: // ADD, SLL, SLT, SLTU, XOR, SRL, OR, AND
                    switch (insn.range(14, 12)) {
                    case FUNCT3_ADD:
                        output.alu_op = ALUOP_ADD;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_ADD";
                        #endif
                        break;
                    case FUNCT3_SLL:
                        output.alu_op = ALUOP_SLL;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_SLL";
                        #endif
                        break;
                    case FUNCT3_SLT:
                        output.alu_op = ALUOP_SLT;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_SLT";
                        #endif
                        break;
                    case FUNCT3_SLTU:
                        output.alu_op = ALUOP_SLTU;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_SLTU";
                        #endif
                        break;
                    case FUNCT3_XOR:
                        output.alu_op = ALUOP_XOR;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_XOR";
                        #endif
                        break;
                    case FUNCT3_SRL:
                        output.alu_op = ALUOP_SRL;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_SRL";
                        #endif
                        break;
                    case FUNCT3_OR:
                        output.alu_op = ALUOP_OR;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_OR";
                        #endif
                        break;
                    case FUNCT3_AND:
                        output.alu_op = ALUOP_AND;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_AND";
                        #endif
                        break;
                    default:
                        output.alu_op = ALUOP_NULL;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_NULL";
                        #endif
                        SC_REPORT_ERROR(sc_object::name(), "Unimplemented ALUOP_ADD instruction");
                        break;
                    }
                    break;
                case FUNCT7_SUB: // SUB, SRA
                    switch (insn.range(14, 12)) {
                    case FUNCT3_SUB:
                        output.alu_op = ALUOP_SUB;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_SUB";
                        #endif
                        break;
                    case FUNCT3_SRA:
                        output.alu_op = ALUOP_SRA;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_SRA";
                        #endif
                        break;
                    default:
                        output.alu_op = ALUOP_NULL;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_NULL";
                        #endif
                        SC_REPORT_ERROR(sc_object::name(), "Unimplemented ALUOP_SUB instruction");
                        break;
                    }
                    break;
                    #if defined(MUL32) || defined(MUL64) || defined(DIV) || defined(REM)
                case FUNCT7_MUL: // MUL, MULH, MULHSU, MULHU, DIV, DIVU, REM, REMU
                    switch (insn.range(14, 12)) {
                    case FUNCT3_MUL:
                        output.alu_op = ALUOP_MUL;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_MUL";
                        #endif
                        break;
                    case FUNCT3_MULH:
                        output.alu_op = ALUOP_MULH;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_MULH";
                        #endif
                        break;
                    case FUNCT3_MULHSU:
                        output.alu_op = ALUOP_MULHSU;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_MULHSU";
                        #endif
                        break;
                    case FUNCT3_MULHU:
                        output.alu_op = ALUOP_MULHU;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_MULHU";
                        #endif
                        break;
                    case FUNCT3_DIV:
                        output.alu_op = ALUOP_DIV;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_DIV";
                        #endif
                        break;
                    case FUNCT3_DIVU:
                        output.alu_op = ALUOP_DIVU;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_DIVU";
                        #endif
                        break;
                    case FUNCT3_REM:
                        output.alu_op = ALUOP_REM;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_REM";
                        #endif
                        break;
                    case FUNCT3_REMU:
                        output.alu_op = ALUOP_REMU;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_REMU";
                        #endif
                        break;
                    default:
                        output.alu_op = ALUOP_NULL;

                        #ifndef __SYNTHESIS__
                        debug_dout_t.alu_op = "ALUOP_NULL";
                        #endif
                        SC_REPORT_ERROR(sc_object::name(), "Unimplemented ALUOP_MUL instruction");
                        break;
                    }
                    break;
                    #endif
                default:
                    output.alu_op = ALUOP_NULL;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.alu_op = "ALUOP_NULL";
                    #endif
                    SC_REPORT_ERROR(sc_object::name(), "Unimplemented ALUOP instruction");
                    break;
                }
                break;

                #ifdef CSR_LOGIC
            case OPC_SYSTEM:
                output.alu_op = ALUOP_NULL;
                output.alu_src = ALUSRC_RS2;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.memtoreg = 0;
                output.regwrite = 1;

                #ifndef __SYNTHESIS__
                debug_dout_t.alu_op = "ALUOP_NULL";
                debug_dout_t.alu_src = "ALUSRC_RS2";
                debug_dout_t.ld = "NO_LOAD";
                debug_dout_t.st = "NO_STORE";
                debug_dout_t.memtoreg = "MEMTOREG NO";
                debug_dout_t.regwrite = "REGWRITE YES";
                #endif
                switch (insn.range(14, 12)) {
                case FUNCT3_EBREAK: // EBREAK, ECALL
                    output.regwrite = 0;
                    trap = 1;
                    output.alu_op = ALUOP_CSRRWI;
                    output.imm_u.range(19, 8) = (sc_uint<CSR_ADDR>)MCAUSE_A; // force the CSR address to MCAUSE's

                    #ifndef __SYNTHESIS__
                    debug_dout_t.alu_op = "ALUOP_CSRRWI";
                    debug_dout_t.imm_u.range(10, 8) = (sc_uint<3>)MCAUSE_A;
                    #endif
                    if (insn[20] == FUNCT7_EBREAK) { // Bit 20 discriminates b/n EBREAK and ECALL
                        // EBREAK and ECALL leverage CSRRWI decoding to write into the MCAUSE register
                        // but keep regwrite to "0" to prevent writeback
                        trap_cause = EBREAK_CAUSE; // may be not necessary but is kept for future implementations
                        output.imm_u.range(7, 3) = (sc_uint<ZIMM_SIZE>)EBREAK_CAUSE; // force the exception cause on the zimm field

                        #ifndef __SYNTHESIS__
                        debug_dout_t.imm_u.range(7, 3) = (sc_uint<ZIMM_SIZE>)EBREAK_CAUSE;
                        #endif
                    } else { // FUNCT7_ECALL
                        trap_cause = ECALL_CAUSE; // may be not necessary but is kept for future implementations
                        output.imm_u.range(7, 3) = (sc_uint<ZIMM_SIZE>)ECALL_CAUSE; // force the exception cause on the zimm field

                        #ifndef __SYNTHESIS__
                        debug_dout_t.imm_u.range(7, 3) = (sc_uint<ZIMM_SIZE>)ECALL_CAUSE;
                        #endif
                    }
                    break;
                case FUNCT3_CSRRW:
                    output.alu_op = ALUOP_CSRRW;
                    trap = 0;
                    trap_cause = NULL_CAUSE;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.alu_op = "ALUOP_CSRRW";
                    #endif
                    break;
                case FUNCT3_CSRRS:
                    output.alu_op = ALUOP_CSRRS;
                    trap = 0;
                    trap_cause = NULL_CAUSE;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.alu_op = "ALUOP_CSRRS";
                    #endif
                    break;
                case FUNCT3_CSRRC:
                    output.alu_op = ALUOP_CSRRC;
                    trap = 0;
                    trap_cause = NULL_CAUSE;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.alu_op = "ALUOP_CSRRC";
                    #endif
                    break;
                case FUNCT3_CSRRWI:
                    output.alu_op = ALUOP_CSRRWI;
                    output.regwrite = 1;
                    trap = 0;
                    trap_cause = NULL_CAUSE;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.alu_op = "ALUOP_CSRRWI";
                    debug_dout_t.regwrite = "REGWRITE YES";
                    #endif
                    break;
                case FUNCT3_CSRRSI:
                    output.alu_op = ALUOP_CSRRSI;
                    trap = 0;
                    trap_cause = NULL_CAUSE;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.alu_op = "ALUOP_CSRRSI";
                    #endif
                    break;
                case FUNCT3_CSRRCI:
                    output.alu_op = ALUOP_CSRRCI;
                    trap = 0;
                    trap_cause = NULL_CAUSE;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.alu_op = "ALUOP_CSRRCI";
                    #endif
                    break;
                default:
                    output.alu_op = ALUOP_NULL;
                    trap = 0;
                    trap_cause = NULL_CAUSE;

                    #ifndef __SYNTHESIS__
                    debug_dout_t.alu_op = "ALUOP_NULL";
                    #endif
                    SC_REPORT_ERROR(sc_object::name(), "Unimplemented SYSTEM instruction");
                    break;
                }
                break;
                #endif // --- End of System instructions decoding

            default: // illegal instruction
                output.alu_src = ALUSRC_RS2;
                output.regwrite = 0;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.memtoreg = 0;
                trap = 1;
                trap_cause = ILL_INSN_CAUSE;
                output.alu_op = ALUOP_CSRRWI;
                output.imm_u.range(19, 8) = (sc_uint<CSR_ADDR>)MCAUSE_A; // force the CSR address to MCAUSE's

                #ifndef __SYNTHESIS__
                debug_dout_t.alu_src = "ALUSRC_RS2";
                debug_dout_t.regwrite = "REGWRITE NO";
                debug_dout_t.ld = "NO_LOAD";
                debug_dout_t.st = "NO_STORE";
                debug_dout_t.memtoreg = "MEMTOREG NO";
                debug_dout_t.alu_op = "ALUOP_CSRRWI";
                debug_dout_t.imm_u.range(18, 8) = (sc_uint<12>)MCAUSE_A;
                debug_dout_t.imm_u.range(7, 3) = (sc_uint<5>)ILL_INSN_CAUSE;
                #endif

                SC_REPORT_ERROR(sc_object::name(), "Unimplemented instruction");
                break;
            } // --- END of OPCODE switch
            // *** END of control word generation.
            sc_uint <1> sen1_test = sentinel[rs1_addr].range(0, 0);
            sc_uint <1> sen2_test = sentinel[rs2_addr].range(0, 0);    

            sc_uint <XLEN> curr_temp_rs2 = 0;
            if (output.alu_src == ALUSRC_RS2) {
                curr_temp_rs2 = output.rs2;

            } else if (output.alu_src == ALUSRC_IMM_I) {
                curr_temp_rs2.range(11, 0) = output.imm_u.range(19, 8);
                if (output.imm_u[19] == 1) {
					curr_temp_rs2.range(31 ,12) = (sc_uint < 20 >) 1048575;
				}
            } else if (output.alu_src == ALUSRC_IMM_S) {
				curr_temp_rs2.range(4, 0) = output.dest_reg;
                curr_temp_rs2.range(11 ,5) = output.imm_u.range(19, 13);
                 if (curr_temp_rs2[11] == 1) {
					curr_temp_rs2.range(31, 12) = (sc_uint < 20 >) 1048575;
				}

            } else {
				curr_temp_rs2.range(11, 0) = (sc_uint < 12 >) 0; 
				curr_temp_rs2.range(31, 12) = output.imm_u.range(19, 0);
            }

            sc_uint < XLEN > last_ldst_addr = (output.rs1 + curr_temp_rs2);
            last_ldst_index_temp = last_ldst_addr.range(1 + DCACHE_OFFSET_WIDTH + DCACHE_INDEX_WIDTH, 2 + DCACHE_OFFSET_WIDTH);

            if ((output.ld != NO_LOAD || output.st != NO_STORE) && (last_ldst_index_temp == last_ldst_index) && last_ldst_valid && !freeze) {
                load_instruction = true;
                load_pc = pc;
            }

            freeze = false;
            if (load_instruction || (sen1_test && !forward_success_rs1) || (sen2_test && !forward_success_rs2)) {
				freeze = true;
			}  

            sc_uint < 1 > out_regwrite = output.regwrite;
            sc_uint < 33 > sen_input;

            if (!freeze && output.regwrite[0] == 1 && output.dest_reg != 0) {
                sentinel[output.dest_reg].range(XLEN, 1) = pc; // Set corresponding sentinel flag.
                sentinel[output.dest_reg][0] = 1;

                if (output.dest_reg == rs1_addr) {
                    forward_success_rs1 = true;
                } else if (output.dest_reg == rs2_addr) {
                    forward_success_rs2 = true;
                }
            }

            // *** Transform instruction into nop when freeze is active
            if (insn == 0 || freeze) {
                // Bubble.
                output.regwrite = 0;
                output.ld = NO_LOAD;
                output.st = NO_STORE;
                output.alu_op = ALUOP_NULL;
                fetch_out.ras_update = false;
				fetch_out.btb_update = false;
                #ifndef __SYNTHESIS__
                debug_dout_t.regwrite = "REGWRITE NO";
                debug_dout_t.ld = "NO_LOAD";
                debug_dout_t.st = "NO_STORE";
                #endif
            }

            if (output.ld != NO_LOAD || output.st != NO_STORE) {
				last_ldst_index = last_ldst_index_temp;
				last_ldst_valid = true;
			}else {
				last_ldst_valid = false;
			}

            if (!freeze) {
				fetch_dout.Push(fetch_out);
			}
			dout.Push(output);

            #ifndef __SYNTHESIS__
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "load_instruction=" << load_instruction << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "insn=" << insn << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "freeze= " << freeze << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "flush= " << flush << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "pc= " << debug_dout_t.pc << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "regwrite= " << debug_dout_t.regwrite << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "memtoreg= " << debug_dout_t.memtoreg << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "ld= " << debug_dout_t.ld << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "st= " << debug_dout_t.st << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "alu_op= " << debug_dout_t.alu_op << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "alu_src= " << debug_dout_t.alu_src << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "rs1= " << debug_dout_t.rs1 << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "rs2= " << debug_dout_t.rs2 << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "dest_reg= " << debug_dout_t.dest_reg << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "imm_u= " << debug_dout_t.imm_u << endl);
            DPRINT(endl);

            for (int i = 0; i < REG_NUM;) {
                DPRINT(endl);
                for (int j = 0; j < 8; j++) {
                    int r = regfile[i].to_int();
                    DPRINT(" " << std::right << std::setfill(' ') << std::setw(2) << i << ": 0x" << std::hex << std::left << std::setfill(' ') << std::setw(10) << r << std::dec);
                    i++;
                    if (i == REG_NUM)
                        break;
                }
                DPRINT(endl);
                if (i == REG_NUM)
                    break;
            }
            DPRINT(endl);
            #endif

            wait();

        } // *** ENDOF while(true)
    } // *** ENDOF sc_cthread

    // --- Utility functions.

    // Sign extend UJ insn.
    sc_uint < PC_LEN > sign_extend_jump(sc_uint < 21 > imm) {
        if (imm[20] == 1) {
			sc_uint < 32 > ext_imm = 4294967295;
            ext_imm.range(20, 0) = imm;
            return ext_imm;
        }
        else {
			sc_uint < 32 > ext_imm = imm;
			return ext_imm;
		}
    }

    // Sign extend branch insn.
    sc_uint < PC_LEN > sign_extend_branch(sc_uint < 13 > imm) {

        if (imm[12] == 1) {
			sc_uint < 32 > ext_imm = 4294967295;
            ext_imm.range(12, 0) = imm;
            return ext_imm;
        }
        else {
			sc_uint < 32 > ext_imm = imm;
			return ext_imm;
		}
    }

    // --- End of utility functions.
};

#endif

