        if (!(btb_update == other.btb_update))
            return false;
        if (!(ras_update == other.ras_update))
            return false;
        if (!(branch_taken == other.branch_taken))
            return false;   
        if (!(pc == other.pc))
            return false;
        if (!(bta == other.bta))
            return false;
        return true;
    }

    //
