/*	
	@author VLSI Lab, EE dept., Democritus University of Thrace

	@brief 
	Header file for execute stage.
	Division algorithm for DIV, DIVU, REM, REMU instructions. Division by zero
	and overflow semantics are compliant with the RISC-V specs (page 32).

	@note Changes from HL5

		- Use of HLSLibs connections for communication with the rest of the processor.

		- Stall functionality

		- Consists of only one thread


*/

#ifndef __EXECUTE__H
#define __EXECUTE__H

#ifndef NDEBUG
    #include <iostream>
    #define DPRINT(msg) std::cout << msg;
#endif

#define BIT(_N)(1 << _N)

#include "drim4hls_datatypes.h"
#include "defines.h"
#include "globals.h"

#include <mc_connections.h>

// Signed division quotient and remainder struct.
struct div_res_t {
    sc_int < XLEN > quotient;
    sc_int < XLEN > remainder;
};

// Unsigned division quotient and remainder struct.
struct u_div_res_t {
    sc_uint < XLEN > quotient;
    sc_uint < XLEN > remainder;
};

SC_MODULE(execute) {

    #ifndef __SYNTHESIS__
    struct debug_exe_out // TODO: fix all sizes
    {
        //
        // Member declarations.
        //
        sc_uint < 3 > ld;
        sc_uint < 2 > st;
        sc_uint < 1 > memtoreg;
        sc_uint < 1 > regwrite;
        sc_uint < XLEN > alu_res;
        sc_uint < DATA_SIZE > mem_datain;
        sc_uint < REG_ADDR > dest_reg;
        sc_uint < TAG_WIDTH > tag;
        std::string alu_src;
        std::string alu_op;

    }
    debug_exe_out_t;
    #endif
    // Clock and reset signals
    sc_in < bool > CCS_INIT_S1(clk);
    sc_in < bool > CCS_INIT_S1(rst);

    // FlexChannel initiators
    Connections::In < de_out_t > CCS_INIT_S1(din);
    Connections::Out < exe_out_t > CCS_INIT_S1(dout);
    // Forward
    Connections::Out < reg_forward_t > CCS_INIT_S1(fwd_exe);

    // Member variables
    de_out_t data_in;
    de_out_t input;
    exe_out_t output;
    dmem_in_t dmem_din;
    reg_forward_t forward;

    sc_uint < XLEN > csr[CSR_NUM]; // Control and status registers.

    bool freeze;

    // Constructor
    SC_CTOR(execute): din("din"), dout("dout"), fwd_exe("fwd_exe"), clk("clk"), rst("rst") {
        SC_THREAD(execute_th);
        sensitive << clk.pos();
        async_reset_signal_is(rst, false);
    }

    u_div_res_t udiv_func(sc_uint < XLEN > num, sc_uint < XLEN > den) {
        sc_uint < XLEN > rem;
        sc_uint < XLEN > quotient;
        u_div_res_t u_div_res;

        rem = 0;
        quotient = 0;

        DIVIDE_LOOP:
            for (sc_int < 6 > i = 31; i >= 0; i--) {
                // Break EXE stage protocol for DSE

                const sc_uint < XLEN > mask = BIT(i);
                const sc_uint < XLEN > lsb = (mask & num) >> i;

                rem = rem << 1;
                rem = rem | lsb;

                if (rem >= den) {
                    rem -= den;
                    quotient = quotient | mask;
                }
                wait();
            }

        u_div_res.quotient = quotient;
        u_div_res.remainder = rem;

        return u_div_res;
    }

    div_res_t div_func(sc_int < XLEN > num, sc_int < XLEN > den) {
        bool num_neg;
        bool den_neg;

right_context:
        u_div_res_t u_div_res;

        num_neg = num < 0;
        den_neg = den < 0;

        if (num_neg)
            num = -num;
        if (den_neg)
            den = -den;

        u_div_res = udiv_func((sc_uint < XLEN > ) num, (sc_uint < XLEN > ) den);
        div_res.quotient = (sc_int < XLEN > ) u_div_res.quotient;
        div_res.remainder = (sc_int < XLEN > ) u_div_res.remainder;

        if (num_neg ^ den_neg)
            div_res.quotient = -div_res.quotient;
        else
            div_res.quotient = div_res.quotient;

        return div_res;
    }

    void execute_th(void) {
        EXE_RST: {
            din.Reset();
            dout.Reset();
            fwd_exe.Reset();

            output.tag = 0;

            csr[MISA_I] = 0x40001101; // RV32IMA
            csr[MARCHID_I] = 0x0; // Not implemented (should be assigned by RISC-V
            csr[MIMPID_I] = 0x0; // Not implemented (processor revision)
            csr[MHARTID_I] = 0x0; // Single thread (always 0)
            csr[MINSTRET_I] = 0x0; // Retired instructions
            csr[MCYCLE_I] = 0x0; // Cycle count (32-bits only for now)

            wait();
        }

        #pragma hls_pipeline_init_interval 1
        #pragma pipeline_stall_mode flush
        EXE_BODY: while (true) {
            input = din.Pop();

            csr[MCYCLE_I]++;            

            // Compute
            output.regwrite = input.regwrite;
            output.memtoreg = input.memtoreg;
            output.ld = input.ld;
            output.st = input.st;
            output.dest_reg = input.dest_reg;
            output.mem_datain = input.rs2;
            output.tag = input.tag;
            output.pc = input.pc;

            bool nop = false;
            if (input.regwrite[0] == 0 &&
                input.ld == NO_LOAD &&
                input.st == NO_STORE &&
                input.alu_op == ALUOP_NULL) {
                nop = true;
            }
            #ifdef MUL64
            // 64-bit temporary multiplication result, for upper 32 bit multiplications (MULH, MULHU, MULHSU).
            //int64_t tmp_mul_res = 0;
            sc_uint <64> tmp_mul_res = 0;
            #endif
            #ifdef DIV
            // Temporary division results.
            div_res_t div_res = {
                0,
                0
            };
            u_div_res_t u_div_res = {
                0,
                0
            };
            #endif
            #ifdef CSR_LOGIC
            // Temporary CSR index
            sc_uint < CSR_IDX_LEN > csr_index = 0;
            #endif

            // Sign extend the immediate operand for I-type instructions.
            sc_uint < XLEN > tmp_sigext_imm_i = 0;
            if (input.imm_u[19] == 1) {
                // Extend with 1s
                tmp_sigext_imm_i = (sc_uint < 20 > (1048575), (sc_uint < 12 > ) input.imm_u.range(19, 8));
            } else {
                // Extend with 0s
                tmp_sigext_imm_i = (sc_uint < 20 > (0), (sc_uint < 12 > ) input.imm_u.range(19, 8));
            }
            // Zero-fill the immediate operand for U-type instructions.
            sc_uint < XLEN > tmp_zerofill_imm_u = ((sc_uint < 20 > ) input.imm_u.range(19, 0), sc_uint < 12 > (0));
            // ALU 2nd operand multiplexing based on ALUSRC signal.
            sc_uint < XLEN > tmp_rs2 = 0;

            if (input.alu_src == ALUSRC_RS2) {
                tmp_rs2 = input.rs2;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_src = "ALUSRC_RS2";
                #endif

            } else if (input.alu_src == ALUSRC_IMM_I) {
                tmp_rs2 = tmp_sigext_imm_i;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_src = "ALUSRC_IMM_I";
                #endif

            } else if (input.alu_src == ALUSRC_IMM_S) {
                // reconstructs imm_s from imm_u and rd
                sc_uint<12> imm_s = (sc_uint<7>(input.imm_u.range(19, 13)), input.dest_reg);
                tmp_rs2 = sign_extend_imm_s(imm_s);

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_src = "ALUSRC_IMM_S";
                #endif

            } else {
                // ALUSRC_IMM_U
                tmp_rs2 = tmp_zerofill_imm_u;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_src = "ALUSRC_IMM_U";
                #endif
            }

            // ALU body
            switch (input.alu_op) {
            case ALUOP_ADD: // ADD, ADDI, SB, SH, SW, LB, LH, LW, LBU, LHU.
                output.alu_res = (sc_uint<32>) input.rs1.to_int() + tmp_rs2.to_int();

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_ADD";
                #endif

                break;
            case ALUOP_SLT: // SLT, SLTI
                if ((sc_int<32>) input.rs1 < (sc_int<32>) tmp_rs2)
                    output.alu_res = 1;
                else
                    output.alu_res = 0;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_SLT";
                #endif

                break;
            case ALUOP_SLTU: // SLTU, SLTIU
                if ((sc_uint<32>) input.rs1  < (sc_uint<32>) tmp_rs2)
                    output.alu_res = 1;
                else
                    output.alu_res = 0;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_SLTU";
                #endif

                break;
            case ALUOP_XOR: // XOR, XORI
                output.alu_res = input.rs1 ^ tmp_rs2;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_XOR";
                #endif

                break;
            case ALUOP_OR: // OR, ORI
                output.alu_res = input.rs1 | tmp_rs2;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_OR";
                #endif

                break;
            case ALUOP_AND: // AND, ANDI
                output.alu_res = input.rs1 & tmp_rs2;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_AND";
                #endif

                break;
            case ALUOP_SLL: // SLL
                output.alu_res = (sc_uint < XLEN >) input.rs1 << (sc_uint < SHAMT >) tmp_rs2.range(4, 0);

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_SLL";
                #endif

                break;
            case ALUOP_SRL: // SRL
                output.alu_res = (sc_uint < XLEN >) input.rs1 >> (sc_uint < SHAMT >) tmp_rs2.range(4, 0);

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_SRL";
                #endif

                break;
            case ALUOP_SRA: // SRA
                // >> is arith right sh. for sc_int operand
                output.alu_res = (sc_int < XLEN >) input.rs1 >> (sc_uint < SHAMT >) tmp_rs2.range(4, 0);

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_SRA";
                #endif

                break;
            case ALUOP_SUB: // SUB
                output.alu_res = (sc_uint < XLEN >) ((sc_int < XLEN >) input.rs1 - (sc_int < XLEN >) tmp_rs2);

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_SUB";
                #endif

                break;
            case ALUOP_SLLI: // SLLI
                output.alu_res = (sc_uint < XLEN >) input.rs1 << (sc_uint < SHAMT >) tmp_rs2.range(24, 20);

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_SLLI";
                #endif

                break;
            case ALUOP_SRLI: // SRLI
                output.alu_res = (sc_uint < XLEN >) input.rs1 >> (sc_uint < SHAMT >) tmp_rs2.range(24, 20);

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_SRLI";
                #endif

                break;
            case ALUOP_SRAI: // SRAI
                // >> is arith right sh. for sc_int operand
                output.alu_res = (sc_int < XLEN >) input.rs1 >> (sc_uint < SHAMT >) tmp_rs2.range(24, 20);

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_SRAI";
                #endif

                break;
            case ALUOP_LUI: // LUI
                // zerofill_imm_u
                output.alu_res = tmp_rs2;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_LUI";
                #endif

                break;
            case ALUOP_AUIPC: // AUIPC
                // zerofill_imm_u + pc
                output.alu_res = (sc_int < XLEN >) tmp_rs2 + (sc_int < XLEN >) input.pc;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_AUIPC";
                #endif

                break;
            case ALUOP_JAL: // JAL, JALR
                // link register update
                output.alu_res = (sc_int < XLEN >) input.pc + 4;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_JAL";
                #endif

                break;
                #ifdef MUL32
            case ALUOP_MUL: // MUL: signed * signed, return lower 32 bits
                output.alu_res = (sc_int < XLEN >) input.rs1 * (sc_int < XLEN >) tmp_rs2;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_MUL";
                #endif

                break;
                #endif
                #ifdef MUL64
            case ALUOP_MULH: // MULH: signed * signed, return upper 32 bits
                tmp_mul_res = input.rs1.to_int() * tmp_rs2.to_int();
                output.alu_res = sc_uint<XLEN*2>(sc_int<XLEN*2>(tmp_mul_res)).range((XLEN*2)-1, XLEN);

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_MULH";
                #endif

                break;
            case ALUOP_MULHSU: // MULHSU: signed * unsigned, return upper 32 bits
                tmp_mul_res = input.rs1 * tmp_rs2.to_uint();
                output.alu_res = sc_uint<XLEN*2>(sc_int<XLEN*2>(tmp_mul_res)).range((XLEN*2)-1, XLEN);

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_MULHSU";
                #endif

                break;
            case ALUOP_MULHU: // MULHU: unsigned * unsigned, return upper 32 bits
                tmp_mul_res = input.rs1.to_int() * tmp_rs2.to_uint();
                output.alu_res = sc_uint<XLEN*2>(sc_int<XLEN*2>(tmp_mul_res)).range((XLEN*2)-1, XLEN);

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_MULHU";
                #endif

                break;
                #endif
                #ifdef DIV
            case ALUOP_DIV: // DIV calls div_func
                div_res = div_func((sc_int < XLEN >) input.rs1, (sc_int < XLEN >) tmp_rs2);
                output.alu_res = div_res.quotient;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_DIV";
                #endif

                break;
            case ALUOP_DIVU: // DIVU calls udiv_func
                u_div_res = udiv_func(input.rs1.to_uint(), tmp_rs2.to_uint());
                output.alu_res = u_div_res.quotient;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_DIVU";
                #endif

                break;
                #endif
                #ifdef REM
            case ALUOP_REM: // REM calls div_func
                div_res = div_func((sc_int < XLEN >) input.rs1, (sc_int < XLEN >) tmp_rs2);
                output.alu_res = div_res.remainder;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_REM";
                #endif

                break;
            case ALUOP_REMU: // REMU calls udiv_func
                u_div_res = udiv_func( input.rs1.to_uint(), tmp_rs2.to_uint());
                output.alu_res = u_div_res.remainder;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_REMU";
                #endif

                break;
                #endif
                #ifdef CSR_LOGIC
                // All CSRx instructions exploit imm_u[19:8] to get the csr address.
                // This avoids having 12 more bits on the FEDEC-EXE Flex Channel.
                // The same goes for imm_u[7:3] i.e. zimm for the 3 CSRxI instructions.
            case ALUOP_CSRRW: // CSRRW
                csr_index = get_csr_index(input.imm_u.range(19, 8));
                output.alu_res = csr[csr_index];
                set_csr_value(csr_index, input.rs1.to_uint(), CSR_OP_WR, input.imm_u.range(19, 18).to_uint());

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_CSRRW";
                #endif

                break;
            case ALUOP_CSRRS: // CSRRS
                csr_index = get_csr_index(input.imm_u.range(19, 8));
                output.alu_res = csr[csr_index];
                set_csr_value(csr_index, input.rs1.to_uint(), CSR_OP_SET, input.imm_u.range(19, 18).to_uint());

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_CSRRS";
                #endif

                break;
            case ALUOP_CSRRC: // CSRRC
                csr_index = get_csr_index(input.imm_u.range(19, 8));
                output.alu_res = csr[csr_index];
                set_csr_value(csr_index, input.rs1.to_uint(), CSR_OP_CLR, input.imm_u.range(19, 18).to_uint());

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_CSRRC";
                #endif

                break;
            case ALUOP_CSRRWI: // CSRRWI
                csr_index = get_csr_index(input.imm_u.range(19, 8));
                output.alu_res = csr[csr_index];
                set_csr_value(csr_index, input.imm_u.range(7, 3).to_uint(), CSR_OP_WR, input.imm_u.range(19, 18).to_uint());

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_CSRRWI";
                #endif

                break;
            case ALUOP_CSRRSI: // CSRRSI
                csr_index = get_csr_index(input.imm_u.range(19, 8));
                output.alu_res = csr[csr_index];
                set_csr_value(csr_index, input.imm_u.range(7, 3).to_uint(), CSR_OP_SET, input.imm_u.range(19, 18).to_uint());

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_CSRRSI";
                #endif

                break;
            case ALUOP_CSRRCI: // CSRRCI
                csr_index = get_csr_index(input.imm_u.range(19, 8));
                output.alu_res = csr[csr_index];
                set_csr_value(csr_index, input.imm_u.range(7, 3).to_uint(), CSR_OP_CLR, input.imm_u.range(19, 18).to_uint());

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_CSRRCI";
                #endif

                break;
                #endif
            default: // ALUOP_NULL (do nothing)
                output.alu_res = 0;

                #ifndef __SYNTHESIS__
                debug_exe_out_t.alu_op = "ALUOP_NULL";
                #endif

                break;
            }

            if ((input.ld != NO_LOAD || input.st != NO_STORE) && !nop) {
                forward.ldst = true;
            } else {
                forward.ldst = false;
            }

            if (output.alu_res == ALUOP_NULL) {
                forward.ldst = true;
            }

            if (!nop) {
                forward.tag = output.tag;
                forward.regfile_data = output.alu_res;
                forward.pc = input.pc;
            }

            if (!nop)
               csr[MINSTRET_I]++;

            // Put
			fwd_exe.Push(forward);
            dout.Push(output);
            #ifndef __SYNTHESIS__
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "nop " << nop << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "pc= " << input.pc << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "forward.regfile_data " << forward.regfile_data << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "forward.tag " << forward.tag << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "output.alu_op " << debug_exe_out_t.alu_op << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "output.alu_res " << output.alu_res << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "output.ld " << output.ld << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "output.st " << output.st << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "output.regwrite  " << output.regwrite << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "output.dest_reg  " << output.dest_reg << endl);
            DPRINT(endl);
            #endif

            wait();
        }
    }

    /* Support functions */

    // Sign extend immS.
    sc_uint < XLEN > sign_extend_imm_s(sc_uint < 12 > imm) {
        sc_uint <XLEN> imm_ext = 0;
        if (imm[11] == 1) {
			// Extend with 1s
			imm_ext.range(11, 0) = imm;
			imm_ext.range(31, 12) = (sc_uint < 20 >) 1048575;
            return imm_ext;
        }
        else { 
			// Extend with 0s
			imm_ext.range(11 , 0) = imm;
            return imm_ext;
        }
    }

    #ifdef CSR_LOGIC
    // Zero extends the zimm immediate field of CSRRWI, CSRRSI, CSRRCI
    sc_uint < XLEN > zero_ext_zimm(sc_uint < ZIMM_SIZE > zimm) {
        sc_uint <XLEN> zimm_ext = 0;
        zimm_ext.range(4, 0) = zimm;
        return zimm_ext;
    }

    // Return index given a csr address.
    sc_uint < CSR_IDX_LEN > get_csr_index(sc_uint < CSR_ADDR > csr_addr) {
        switch (csr_addr) {
        case USTATUS_A:
            return USTATUS_I;
        case MSTATUS_A:
            return MSTATUS_I;
        case MISA_A:
            return MISA_I;
        case MTVECT_A:
            return MTVECT_I;
        case MEPC_A:
            return MEPC_I;
        case MCAUSE_A:
            return MCAUSE_I;
        case MCYCLE_A:
            return MCYCLE_I;
        case MARCHID_A:
            return MARCHID_I;
        case MIMPID_A:
            return MIMPID_I;
        case MINSTRET_A:
            return MINSTRET_I;
        case MHARTID_A:
            return MHARTID_I;
        default:
            return 6; // TODO: this is not ideal. I default unsupported CSRs to MARCHID as it's not a critical register.
        }
    }

    // Set value of csr[csr_addr]
    // TODO: respect unwritable fields, see manual for each individual implemented CSR.
    // TODO: for now any bits of every register are fully readable/writeable.
    // TODO: This must be changed in future implementations.
    void set_csr_value(sc_uint < CSR_IDX_LEN > csr_index, sc_uint < XLEN > rs1, sc_uint < LOG2_CSR_OP_NUM > operation, sc_uint < 2 > rw_permission) {
        if (rw_permission != 3)
            switch (operation) {
            case CSR_OP_WR:
                csr[csr_index] = rs1.to_uint();
                break;
            case CSR_OP_SET:
                csr[csr_index] |= rs1.to_uint();
                break;
            case CSR_OP_CLR:
                csr[csr_index] &= ~(rs1.to_uint());
                break;
            default:
                break;
            }
    }
    #endif
};

#endif

left_context:
/*	
	@author VLSI Lab, EE dept., Democritus University of Thrace

	@brief Header file for fetch stage

	@note Changes from HL5
		- Implements the logic only for the fetch part from fedec.hpp.

		- Use of HLSLibs connections for communication with the rest of the processor.

		- Increment program counter based on new stall functionality.


*/

#ifndef __FETCH__H
#define __FETCH__H

#ifndef NDEBUG
    #include <iostream>
    #define DPRINT(msg) std::cout << msg;
#endif


#include "drim4hls_datatypes.h"
#include "defines.h"
#include "globals.h"

#include <mc_connections.h>
#include <ac_int.h>

SC_MODULE(fetch) {
    public:
    // Clock and reset signals
    sc_in < bool > CCS_INIT_S1(clk);
    sc_in < bool > CCS_INIT_S1(rst);
    // Channel ports
    Connections::In < fe_in_t > CCS_INIT_S1(fetch_din);
    Connections::In < imem_out_t > CCS_INIT_S1(imem_dout);
    Connections::Out < imem_in_t > CCS_INIT_S1(imem_din);
    Connections::Out < fe_out_t > CCS_INIT_S1(dout);

    // Trap signals. TODO: not used. Left for future implementations.
    sc_signal < bool > CCS_INIT_S1(trap); //sc_out
    sc_signal < ac_int < LOG2_NUM_CAUSES, false > > CCS_INIT_S1(trap_cause); //sc_out

    // *** Internal variables
    sc_int < PC_LEN > pc; // Init. to -4, then before first insn fetch it will be updated to 0.	 
    sc_uint < PC_LEN > imem_pc; // Used in fetching from instruction memory
	sc_uint < PC_LEN > pc_tmp; // Init. to -4, then before first insn fetch it will be updated to 0. 
    // Custom datatypes used for retrieving and sending data through the channels
    imem_in_t imem_in; // Contains data for fetching from the instruction memory
    fe_out_t fe_out; // Contains data for the decode stage
    fe_in_t fetch_in; // Contains data from the decode stage used in incrementing the PC
    imem_out_t imem_out;

    bool redirect;
    bool redirect_tmp;

    ras_data_t ra_stack[RAS_ENTRIES];
    sc_uint < RAS_POINTER_SIZE > ras_pointer;
    sc_uint < RAS_POINTER_SIZE > tosp_pointer;

    sc_uint < PC_LEN > mispredictions;
    sc_uint < PC_LEN > correct_predictions;
    sc_uint < PC_LEN > redirect_addr;

	sc_uint < DATA_SIZE > mem_dout;
    sc_uint < ICACHE_LINE > imem_data;
    sc_uint < XLEN > imem_data_offset;

    sc_uint < ICACHE_TAG_WIDTH + ICACHE_INDEX_WIDTH + 1 > icache_buffer_addr[ICACHE_BUFFER_SIZE][ICACHE_WAYS];
    sc_uint < ICACHE_LINE > icache_buffer_instr[ICACHE_BUFFER_SIZE][ICACHE_WAYS];

    icache_data_t icache_data[ICACHE_ENTRIES][ICACHE_WAYS];
    icache_tag_t icache_tags[ICACHE_ENTRIES][ICACHE_WAYS];
    icache_out_t icache_out;

    icache_data_t cache_data[1][ICACHE_WAYS];
    icache_tag_t cache_tag[1][ICACHE_WAYS];

    btb_data_t btb_data[BTB_ENTRIES];
    btb_out_t btb_out;

    sc_uint < ICACHE_TAG_WIDTH > tag;
    sc_uint < ICACHE_INDEX_WIDTH > index;
    sc_uint < ICACHE_OFFSET_WIDTH + 1 > offset;

    sc_uint < ICACHE_TAG_WIDTH + ICACHE_INDEX_WIDTH > buffer_addr;

    bool freeze;
    bool hit_buffer;
    int position;

    SC_CTOR(fetch): imem_din("imem_din"),
    fetch_din("fetch_din"),
    dout("dout"),
    imem_dout("imem_dout"),
    clk("clk"),
    rst("rst") {
        SC_THREAD(fetch_th);
        sensitive << clk.pos();
        async_reset_signal_is(rst, false);

    }

    void fetch_th(void) {
        FETCH_RST: {
            dout.Reset();
            fetch_din.Reset();
            imem_din.Reset();
            imem_dout.Reset();

            tag = 0;
            index= 0;
            offset = 0;
            position = 0;

            trap = 0;
            trap_cause = NULL_CAUSE;
            imem_in.instr_addr = 0;

			ras_pointer = 0;
			tosp_pointer = 0;

            redirect_addr = 0;
			freeze = false;
			redirect = false;
            //  Init. pc to START_ADDRESS - 4 as on first fetch it will be incremented by
            //  4, thus fetching instruction at address 0
            pc = 0;
            pc_tmp = -4;
            buffer_addr = 0;

            int n = 0;

right_context:
            for (n = 0; n < ICACHE_BUFFER_SIZE; n++) {
                for (l = 0; l < ICACHE_WAYS; l++) {             
				    icache_buffer_addr[n][l] = 0;
				    icache_buffer_instr[n][l] = 0;
				}
			}

			mispredictions = 0;
			correct_predictions = 0;

            wait();
        }
        #pragma hls_pipeline_init_interval 1
        #pragma pipeline_stall_mode flush
        FETCH_BODY: while (true) {
            //sc_assert(sc_time_stamp().to_double() < 1500000);

			// step 1 fetch from memory/cache
            hit_buffer = false;
            fe_out.pc = pc;

            unsigned int aligned_addr = pc >> 2;
            imem_in.instr_addr = aligned_addr;

            sc_uint < XLEN > addr = aligned_addr;

            tag = addr.range(ICACHE_TAG_WIDTH + ICACHE_INDEX_WIDTH + ICACHE_OFFSET_WIDTH - 1, ICACHE_INDEX_WIDTH + ICACHE_OFFSET_WIDTH);
            index = addr.range(ICACHE_INDEX_WIDTH + ICACHE_OFFSET_WIDTH - 1,ICACHE_OFFSET_WIDTH);        
			if (ICACHE_OFFSET_WIDTH) {
                offset = addr.range(ICACHE_OFFSET_WIDTH - 1, 0);
            }
            else {
				offset = 0;
			}

			buffer_addr.range(ICACHE_INDEX_WIDTH - 1, 0) = index;
			buffer_addr.range (ICACHE_TAG_WIDTH + ICACHE_INDEX_WIDTH - 1, ICACHE_INDEX_WIDTH) = tag;

			int m = 0;
			int n = 0;
			int k = ICACHE_BUFFER_SIZE - 1;

			for (k; k > 0; k = k - 1) {
				for (m = 0; m < ICACHE_WAYS; m++) {
					icache_buffer_addr[k][m] = icache_buffer_addr[k-1][m];
					icache_buffer_instr[k][m] = icache_buffer_instr[k-1][m]; 
				}                 
			}

			icache_out = icache();

			for (m = 0; m < ICACHE_WAYS; m++) {                 
				icache_buffer_instr[0][m] = cache_data[0][m].data;
				icache_buffer_addr[0][m].range(0, 0) = (ac_int <1, false>) cache_tag[0][m].valid;
				icache_buffer_addr[0][m].range(ICACHE_INDEX_WIDTH, 1) = index;
				icache_buffer_addr[0][m].range(ICACHE_TAG_WIDTH + ICACHE_INDEX_WIDTH, ICACHE_INDEX_WIDTH + 1) = cache_tag[0][m].tag;
			}

			if (!icache_out.hit) {
				for (n = 0; n < ICACHE_BUFFER_SIZE; n++) {
					for (m = 0; m < ICACHE_WAYS; m++) {                 
						if (icache_buffer_addr[n][m].range(ICACHE_TAG_WIDTH + ICACHE_INDEX_WIDTH, 1) == buffer_addr && icache_buffer_addr[n][m].range(0, 0) == 1) {
							icache_out.data = icache_buffer_instr[n][m];
							icache_out.hit = true;
							hit_buffer = true;
						}
					}
				}
			}
			int j = 0;
            switch (icache_out.hit)
            {
				case CACHE_HIT:
                    imem_data = icache_out.data;

                    #pragma unroll yes
					for (int i = 0; i < DATA_WIDTH; i++) {
						int index = offset*DATA_WIDTH + i;
						imem_data_offset[i] = imem_data[index];
					}

                    fe_out.instr_data = imem_data_offset;
                    break;
                case CACHE_MISS:

                    imem_din.Push(imem_in);

					imem_out = imem_dout.Pop();

                    imem_data = imem_out.instr_data;
					#pragma unroll yes
					for (int i = 0; i < DATA_WIDTH; i++) {
						int index = offset*DATA_WIDTH + i;
						imem_data_offset[i] = imem_data[index];
					}
					fe_out.instr_data = imem_data_offset;

					icache_buffer_addr[0][ICACHE_WAYS - 1].range(0, 0) = 1;
					icache_buffer_addr[0][ICACHE_WAYS - 1].range(ICACHE_TAG_WIDTH + ICACHE_INDEX_WIDTH, 1) = buffer_addr;
					icache_buffer_instr[0][ICACHE_WAYS - 1] = imem_data;

                    break;
                default:
                    break;
            }

			icache_write();

			//step2 read from backchannel (decode)
			if (position == 1 && !redirect) {
				fetch_in = fetch_din.Pop();
				redirect_addr = fetch_in.address;
			}else {
				position = 1;
			}
			// step3 if instruction correct send it, update btb, ras and get new pc
			if (redirect_addr == pc) {
				btb_write();
				ras_write();				
				btb();
				ras();
				pc = (btb_out.btb_valid || btb_out.ras_valid) ? btb_out.bta : (ac_int < PC_LEN, false >)(pc + 4);
				redirect = false;
				dout.Push(fe_out);
			}else { // step4 if instruction incorrect, redirect
				pc = redirect_addr;
				redirect = true;
			}

			#ifndef __SYNTHESIS__
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "pc= " << pc << endl);
            DPRINT(endl);
            #endif
            wait();

        } // *** ENDOF while(true)
    } // *** ENDOF sc_cthread

    icache_out_t icache () {

        icache_out_t iout;
        icache_tag_t tmp_tag;
        icache_data_t tmp_data;
        iout.data = 0;
        iout.hit = false;

		int i = 0;
        int j = 0;

        for (i = 0; i < ICACHE_WAYS; i++) {
            cache_tag[0][i] = icache_tags[index][i];
            cache_data[0][i] = icache_data[index][i];

            if ((tag == cache_tag[0][i].tag) && (cache_tag[0][i].valid)) {

                tmp_data = cache_data[0][i];
                tmp_tag = cache_tag[0][i];
                iout.hit = true;
                j = i;

            }

		}

		for (i = ICACHE_WAYS - 1; i > 0; i--) {
			if (iout.hit && i <= j) {
				cache_data[0][i] = cache_data[0][i-1];
				cache_tag[0][i] = cache_tag[0][i-1];
			}

		}

        if (iout.hit) {

            cache_data[0][0] = tmp_data;
            cache_tag[0][0] = tmp_tag;
		}else {
			tmp_data = cache_data[0][ICACHE_WAYS - 1];
		}

        iout.data = tmp_data.data;

        return iout;
    }

    void icache_write () {

        sc_uint < ICACHE_INDEX_WIDTH > write_index = icache_buffer_addr[1][0].range(ICACHE_INDEX_WIDTH, 1);
        int i = 0;
        for (i = 0; i < ICACHE_WAYS; i++) {                 

			if (hit_buffer) {
				icache_buffer_instr[0][i] = icache_buffer_instr[1][i];
				icache_buffer_addr[0][i] = icache_buffer_addr[1][i];
			}
			icache_data[write_index][i].data = icache_buffer_instr[1][i];
			icache_tags[write_index][i].valid = icache_buffer_addr[1][i].range(0,0);
			icache_tags[write_index][i].tag = icache_buffer_addr[1][i].range(ICACHE_INDEX_WIDTH + ICACHE_TAG_WIDTH, 1 + ICACHE_INDEX_WIDTH);
        }


    }

    void btb () {     
        sc_uint < BTB_INDEX_WIDTH > next_index = pc.range(BTB_INDEX_WIDTH - 1 ,0).to_uint();
		sc_uint < BTB_TAG_WIDTH > next_tag = pc.range(BTB_INDEX_WIDTH + BTB_TAG_WIDTH - 1, BTB_INDEX_WIDTH).to_uint();

        if(next_tag == btb_data[next_index].tag && btb_data[next_index].prediction_data > WEAK_NON_TAKEN) {
            btb_out.bta = btb_data[next_index].bta;
            btb_out.btb_valid = true;
        }
        else {
            btb_out.btb_valid = false;
        }
    }

    void btb_write () {
		sc_uint < PC_LEN > update_pc = fetch_in.pc;
		sc_uint < BTB_INDEX_WIDTH > index = update_pc.range(BTB_INDEX_WIDTH - 1, 0).to_uint();
		sc_uint < BTB_TAG_WIDTH > tag = update_pc.range(BTB_INDEX_WIDTH + BTB_TAG_WIDTH - 1, BTB_INDEX_WIDTH).to_uint();

		btb_data_t data = btb_data[index];
        //check if tag or branch target address differ in branch target buffer
        if (fetch_in.btb_update) {
            if(tag != data.tag || fetch_in.bta != data.bta) {
                btb_data[index].tag = tag;
                btb_data[index].bta = fetch_in.bta;
                btb_data[index].prediction_data = WEAK_NON_TAKEN;
                if (fetch_in.branch_taken) {
					mispredictions++;
				}    

            }else if (fetch_in.branch_taken && btb_data[index].prediction_data < STRONG_TAKEN){
                btb_data[index].prediction_data = btb_data[index].prediction_data + 1;
                if(btb_data[index].prediction_data > WEAK_NON_TAKEN + 1) {
					correct_predictions++;
				}else {
					mispredictions++;
				}
            }else if (!fetch_in.branch_taken && btb_data[index].prediction_data > 0) {
                btb_data[index].prediction_data = btb_data[index].prediction_data - 1;
                if(btb_data[index].prediction_data > WEAK_NON_TAKEN-1) {
					mispredictions++;
				}else {
					correct_predictions++;
				}

            }else {
				correct_predictions++;
			}
        }
	}

	void ras() {

		if (imem_data_offset.range(6, 2) == OPC_JALR && ra_stack[ras_pointer].valid) {
			btb_out.ras_valid = true;
			btb_out.bta = ra_stack[ras_pointer].pc;
			ra_stack[ras_pointer].valid = false;
			tosp_pointer = tosp_pointer - 1;
			ras_pointer = tosp_pointer - 1;
		}else {
			btb_out.ras_valid = false;
		}
	}

	void ras_write() {
		if (fetch_in.ras_update) {
			ra_stack[tosp_pointer].pc = fetch_in.pc + 4;
			ra_stack[tosp_pointer].valid = true;
			tosp_pointer = tosp_pointer + 1;
			ras_pointer = tosp_pointer - 1;
		}
	}
};

#endif

left_context:
/*	
	@author VLSI Lab, EE dept., Democritus University of Thrace

	@brief Header file for writeback stage.

	@note Changes from HL5

		- Use of HLSLibs connections for communication with the rest of the processor.

		- Memory is outside of the processor

*/

#ifndef __WRITEBACK__H
#define __WRITEBACK__H

#ifndef __SYNTHESIS__
    #include <sstream>
#endif

#ifndef NDEBUG
    #include <iostream>
    #define DPRINT(msg) std::cout << msg;
#endif


#include "drim4hls_datatypes.h"
#include "defines.h"
#include "globals.h"

#include <mc_connections.h>

SC_MODULE(writeback) {
    #ifndef __SYNTHESIS__
    struct writeback_out // TODO: fix all sizes
    {
        //
        // Member declarations.
        //		
        unsigned int aligned_address;
        sc_uint < XLEN > load_data;
        sc_uint < XLEN > store_data;
        std::string load;
        std::string store;

    }
    writeback_out_t;
    #endif

    // FlexChannel initiators
    Connections::In < exe_out_t > CCS_INIT_S1(din);
    Connections::In < dmem_out_t > CCS_INIT_S1(dmem_out);

    Connections::Out < mem_out_t > CCS_INIT_S1(dout);
    Connections::Out < dmem_in_t > CCS_INIT_S1(dmem_in);

    // Clock and reset signals
    sc_in < bool > CCS_INIT_S1(clk);
    sc_in < bool > CCS_INIT_S1(rst);

    // Member variables
    exe_out_t input;
    dmem_in_t dmem_dout;
    dmem_out_t dmem_din;
    mem_out_t output;

    sc_uint < DATA_SIZE > mem_dout;
    sc_uint < DCACHE_LINE > dmem_data;
    sc_uint < XLEN > dmem_data_offset;

    dcache_data_t dcache_data[DCACHE_ENTRIES][DCACHE_WAYS];
    dcache_tag_t dcache_tags[DCACHE_ENTRIES][DCACHE_WAYS];
    dcache_out_t dcache_out;

    dcache_data_t cache_data[1][DCACHE_WAYS];
    dcache_tag_t cache_tag[1][DCACHE_WAYS];

    sc_uint < DCACHE_TAG_WIDTH > tag;
    sc_uint < DCACHE_INDEX_WIDTH > index;
    sc_uint < DCACHE_OFFSET_WIDTH + 1 > offset;

    bool freeze;
    // Constructor
    SC_CTOR(writeback): din("din"), dout("dout"), dmem_in("dmem_in"), dmem_out("dmem_out"), clk("clk"), rst("rst") {
        SC_THREAD(writeback_th);
        sensitive << clk.pos();
        async_reset_signal_is(rst, false);
    }

    void writeback_th(void) {
        WRITEBACK_RST: {
            din.Reset();
            dmem_out.Reset();

            dout.Reset();
            dmem_in.Reset();
            // Write dummy data to decode feedback.
            output.regfile_address = 0;
            output.regfile_data = 0;
            output.regwrite = 0;
            output.tag = 0;

			dcache_out.data = 0;
            dcache_out.hit = false;

            dmem_data = 0;
            dmem_data_offset = 0;
            mem_dout = 0;

            tag = 0;
            index = 0;
            offset = 0;

			freeze = false;

        }

        #pragma hls_pipeline_init_interval 1
        #pragma pipeline_stall_mode flush
        WRITEBACK_BODY: while (true) {

            // Get
			input = din.Pop();

            #ifndef __SYNTHESIS__
                writeback_out_t.aligned_address = 0;
                writeback_out_t.load_data = 0;
                writeback_out_t.store_data = 0;
                writeback_out_t.load = "NO_LOAD";
                writeback_out_t.store = "NO_STORE";
            #endif

            // Compute
            // *** Memory access.
			dmem_data = 0;
			dmem_data_offset = 0;
            // WARNING: only supporting aligned memory accesses
            // Preprocess address

            unsigned int aligned_address = input.alu_res.to_uint();
            sc_uint< 5 > byte_index = (sc_uint< 5 >)((aligned_address & 0x3) << 3);
            sc_uint< 5 > halfword_index = (sc_uint< 5 >)((aligned_address & 0x2) << 3);

            aligned_address = aligned_address >> 2;
            sc_uint < BYTE > db = (sc_uint < BYTE >) 0;
            sc_uint < 2 * BYTE > dh = (sc_uint < 2 * BYTE >) 0;
            sc_uint < XLEN > dw = (sc_uint < XLEN >) 0;

            dmem_dout.data_addr = aligned_address;

            dmem_dout.read_en = false;
            dmem_dout.write_en = false;

            sc_uint < XLEN > addr = aligned_address;

            tag = addr.range(DCACHE_INDEX_WIDTH + DCACHE_OFFSET_WIDTH + DCACHE_TAG_WIDTH - 1, DCACHE_INDEX_WIDTH + DCACHE_OFFSET_WIDTH);
            index = addr.range(DCACHE_INDEX_WIDTH + DCACHE_OFFSET_WIDTH - 1, DCACHE_OFFSET_WIDTH);
            if (DCACHE_OFFSET_WIDTH) {
                offset = addr.range(DCACHE_OFFSET_WIDTH - 1, 0);
            }
            else {
				offset = 0;
			}
           //unsigned int max_offset = 1 << DCACHE_OFFSET_WIDTH;

            #ifndef __SYNTHESIS__
            if (sc_uint < 3 > (input.ld) != NO_LOAD || sc_uint < 2 > (input.st) != NO_STORE) {
                if (input.mem_datain.to_uint() == 0x11111111 ||
                    input.mem_datain.to_uint() == 0x22222222 ||
                    input.mem_datain.to_uint() == 0x11223344 ||
                    input.mem_datain.to_uint() == 0x88776655 ||
                    input.mem_datain.to_uint() == 0x12345678 ||
                    input.mem_datain.to_uint() == 0x87654321) {
                    std::stringstream stm;
                    stm << hex << "D$ access here2 -> 0x" << aligned_address << ". Value: " << input.mem_datain.to_uint() << std::endl;
                }
                //sc_assert(aligned_address < DCACHE_SIZE);
            }
            #endif

			if ((input.ld != NO_LOAD || input.st != NO_STORE) && !freeze) { // a load is requested
                dcache_out = dcache();

				int j = 0;
                switch (dcache_out.hit)
                {
                case CACHE_HIT:
                    dmem_data = dcache_out.data;

                    #pragma unroll yes
					for (int i = 0; i < DATA_WIDTH; i++) {
						int index_word = offset*DATA_WIDTH + i;
						dmem_data_offset[i] = dmem_data[index_word];
					}

                    if (cache_tag[0][0].dirty && input.st != NO_STORE && cache_tag[0][0].tag != tag) {
                        dmem_dout.write_en = true;
                        dmem_dout.data_in = dcache_out.data;

right_context:
						dmem_dout.write_addr.range(DCACHE_TAG_WIDTH + DCACHE_INDEX_WIDTH + DCACHE_OFFSET_WIDTH - 1 , DCACHE_INDEX_WIDTH + DCACHE_OFFSET_WIDTH) = cache_tag[0][0].tag;

                        dmem_in.Push(dmem_dout);
                    }

                    break;
                case CACHE_MISS:

                    dmem_dout.read_en = true;
                    if (cache_tag[0][DCACHE_WAYS - 1].dirty && cache_tag[0][DCACHE_WAYS - 1].tag != tag) {
                        dmem_dout.write_en = true;
                        dmem_dout.data_in = dcache_out.data;

                        if (DCACHE_OFFSET_WIDTH) {
							dmem_dout.write_addr = 0;
						}
						dmem_dout.write_addr.range(DCACHE_INDEX_WIDTH + DCACHE_OFFSET_WIDTH - 1, DCACHE_OFFSET_WIDTH) = index;
						dmem_dout.write_addr.range(DCACHE_TAG_WIDTH + DCACHE_INDEX_WIDTH + DCACHE_OFFSET_WIDTH - 1, DCACHE_INDEX_WIDTH + DCACHE_OFFSET_WIDTH) = cache_tag[0][DCACHE_WAYS - 1].tag;
                    }

                    dmem_in.Push(dmem_dout);

                    dmem_din = dmem_out.Pop();
                    dmem_data = dmem_din.data_out;

					#pragma unroll yes
					for (int i = 0; i < DATA_WIDTH; i++) {
						int index_word = offset*DATA_WIDTH + i;
						dmem_data_offset[i] = dmem_data[index_word];
					}

                    dmem_dout.data_in = cache_data[0][DCACHE_WAYS - 1].data;

                    if (input.ld != NO_LOAD) {
						cache_data[0][DCACHE_WAYS - 1].data = dmem_data;
					}

                    break;
                default:
                    break;
                }
            }

            if (input.ld != NO_LOAD) { // a load is requested

                switch (input.ld) { // LOAD
                case LB_LOAD:                    
                    db.range(BYTE - 1, 0) = dmem_data_offset.range(BYTE + byte_index - 1, byte_index);
                    mem_dout = ext_sign_byte(db);

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "LB_LOAD";
                    #endif

                    break;
                case LH_LOAD:
                    dh.range(2*BYTE - 1, 0) = dmem_data_offset.range(2*BYTE + halfword_index - 1, halfword_index);
                    mem_dout = ext_sign_halfword(dh);

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "LH_LOAD";
                    #endif

                    break;
                case LW_LOAD:
                    dw = dmem_data_offset;
                    mem_dout = dw;

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "LW_LOAD";
                    #endif

                    break;
                case LBU_LOAD:
                    db.range(BYTE - 1, 0) = dmem_data_offset.range(BYTE + byte_index - 1, byte_index);
                    mem_dout = ext_unsign_byte(db);

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "LBU_LOAD";
                    #endif

                    break;
                case LHU_LOAD:
                    dh.range(2 * BYTE - 1, 0) = dmem_data_offset.range(2 * BYTE + halfword_index - 1, halfword_index);
                    mem_dout = ext_unsign_halfword(dh);

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "LHU_LOAD";
                    #endif

                    break;
                default:

                    #ifndef __SYNTHESIS__
                    writeback_out_t.load_data = mem_dout;
                    writeback_out_t.load = "NO_LOAD";
                    #endif

                    break; // NO_LOAD
                }
            } else if (input.st != NO_STORE) { // a store is requested

                switch (input.st) { // STORE
                case SB_STORE: // store 8 bits of rs2

					db.range(BYTE - 1, 0) = (sc_uint < BYTE >) input.mem_datain.range(BYTE - 1, 0);
					dmem_data_offset.range(BYTE + byte_index - 1, byte_index) = (sc_uint < BYTE >) db;

                    #ifndef __SYNTHESIS__
                    writeback_out_t.store_data = db;
                    writeback_out_t.store = "SB_STORE";
                    #endif

                    break;
                case SH_STORE: // store 16 bits of rs2

					dh.range(2*BYTE - 1, 0) = input.mem_datain.range(2*BYTE - 1, 0);
					dmem_data_offset.range(2 * BYTE + byte_index - 1, byte_index) = dh;

                    #ifndef __SYNTHESIS__
                    writeback_out_t.store_data = dh;
                    writeback_out_t.store = "SH_STORE";
                    #endif

                    break;
                case SW_STORE: // store rs2
                    dw = input.mem_datain;
                    dmem_data_offset = dw;

                    #ifndef __SYNTHESIS__
                    writeback_out_t.store_data = dw;
                    writeback_out_t.store = "SW_STORE";
                    #endif

					break;
                default:

                    #ifndef __SYNTHESIS__
                    writeback_out_t.store = "NO_STORE";
                    #endif

                    break; // NO_STORE
                }

                #pragma unroll yes
				for (int i = 0; i < DATA_WIDTH; i++) {
					int index_word = offset*DATA_WIDTH + i;
					dmem_data[index_word] = dmem_data_offset[i];
				}

                if (dcache_out.hit) {
                    dmem_dout.data_in = cache_data[0][0].data;
                    cache_data[0][0].data = dmem_data;
                }else {
                    dmem_dout.data_in = cache_data[0][DCACHE_WAYS - 1].data;
                    cache_data[0][DCACHE_WAYS - 1].data = dmem_data;
                }

            }

            bool ld_st_write = (input.st != NO_STORE) ? false : true;

			if ((input.st != NO_STORE || input.ld != NO_LOAD)) {
				dcache_write(ld_st_write, dcache_out.hit);
			}

            // *** END of memory access.

            /* Writeback */
            output.regwrite = input.regwrite;
            output.regfile_address = input.dest_reg;
            output.regfile_data = (input.memtoreg[0] == 1) ? mem_dout : input.alu_res;
            output.tag = input.tag;
            output.pc = input.pc;

            // Put
            freeze = false;
		    dout.Push(output);

            #ifndef __SYNTHESIS__
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "load= " << writeback_out_t.load << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "store= " << writeback_out_t.store << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "input.regwrite=" << input.regwrite << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "regwrite=" << output.regwrite << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << "aligned_address=" << aligned_address << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "mem_dout=" << mem_dout << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "input.alu_res=" << input.alu_res << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "output.regfile_address=" << output.regfile_address << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "output.regfile_data=" << output.regfile_data << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "input.memtoreg=" << input.memtoreg << endl);
            DPRINT("@" << sc_time_stamp() << "\t" << name() << "\t" << std::hex << "writeback_out_t.store_data =" << writeback_out_t.store_data  << endl);
            DPRINT(endl);
            #endif
            wait();
        }
    }

    /* Support functions */

    // Sign extend byte read from memory. For LB
    sc_uint < XLEN > ext_sign_byte(sc_uint < BYTE > read_data) {
		sc_uint <XLEN > extended = 0;
		if (read_data[7] == 1) {
			extended.range(BYTE - 1, 0) = read_data;
			extended.range(BYTE * 4 - 1, BYTE) = (sc_uint < BYTE * 3 >) 16777216;
		}
		else {
			extended.range(BYTE - 1, 0) = read_data;
			extended.range(BYTE * 4 - 1, BYTE) = (sc_uint < BYTE * 3 >) 0;	
		}
		return extended;
    }

    // Zero extend byte read from memory. For LBU
    sc_uint < XLEN > ext_unsign_byte(sc_uint < BYTE > read_data) {
		sc_uint <XLEN> extended = 0;
		extended.range(BYTE - 1, 0) = read_data;
		extended.range(BYTE * 4 - 1, BYTE) = (sc_uint < BYTE * 3 >) 0;	
		return extended;        
    }

    // Sign extend half-word read from memory. For LH
    sc_uint < XLEN > ext_sign_halfword(sc_uint < BYTE * 2 > read_data) {
		sc_uint <XLEN> extended = 0;

        if (read_data[15] == 1) {
			extended.range(BYTE * 2 - 1, 0) = read_data;
			extended.range(BYTE * 4 - 1, 2*BYTE) = (sc_uint < BYTE * 2 >) 65535;
        }
        else {
			extended.range(BYTE * 2 - 1, 0) = read_data;
			extended.range(BYTE * 4 - 1, 2*BYTE) = (sc_uint < BYTE * 2 >) 0;
        }
        return extended;
    }

    // Zero extend half-word read from memory. For LHU
    sc_uint < XLEN > ext_unsign_halfword(sc_uint < BYTE * 2 > read_data) {
		sc_uint <XLEN> extended = 0;
		extended.range(BYTE * 2 - 1, 0) = read_data;
		extended.range(BYTE * 4 - 1, 2*BYTE) = (sc_uint < BYTE * 2 >) 0;
		return extended;
    }

    dcache_out_t dcache () {

        dcache_out_t dout;
        dcache_tag_t tmp_tag;
        dcache_data_t tmp_data;
        dout.data = 0;
        dout.hit = false;

		int i = 0;
        int j = 0;

        for (i = 0; i < DCACHE_WAYS; i++) {
            cache_tag[0][i] = dcache_tags[index][i];
            cache_data[0][i] = dcache_data[index][i];

            if ((tag == cache_tag[0][i].tag) && (cache_tag[0][i].valid)) {

                tmp_data = cache_data[0][i];
                tmp_tag = cache_tag[0][i];
                dout.hit = true;
                j = i;

            }

		}

		for (i = DCACHE_WAYS - 1; i > 0; i--) {
			if (dout.hit && i <= j) {
				cache_data[0][i] = cache_data[0][i-1];
				cache_tag[0][i] = cache_tag[0][i-1];
			}

		}

        if (dout.hit) {

            cache_data[0][0] = tmp_data;
            cache_tag[0][0] = tmp_tag;
		}else {
			tmp_data = cache_data[0][DCACHE_WAYS - 1];
		}

        dout.data = tmp_data.data;

        return dout;
    }

    void dcache_write (bool load, bool hit) {

		unsigned int bank = 0;
        if (!hit) {
            bank = DCACHE_WAYS - 1;
        }


        if (cache_tag[0][bank].dirty && cache_tag[0][bank].tag != tag && !(load && hit)) {

            cache_tag[0][bank].tag = tag;
            cache_tag[0][bank].valid = true;

        } else if (!(load && hit)) { 

            cache_tag[0][bank].tag = tag;
            cache_tag[0][bank].valid = true;
        }

        if (!load) {
            cache_tag[0][bank].dirty = true;
        }else if (!hit){
            cache_tag[0][bank].dirty = false;
        }

        int i = 0;
        for (i = 0; i < DCACHE_WAYS; i++) {                 
            dcache_data[index][i] = cache_data[0][i];
            dcache_tags[index][i] = cache_tag[0][i];

        }      

    }

};

